/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"안전관리 개론(안전조직·리스크관리 용어·안전관리활동 효과)":{"묶음":[{"머리":"안전관리 조직 형태","줄":[{"t":"안전관리 조직 형태는 라인형(Line type), 스태프형(Staff type), 라인스태프형(Line-Staff type)으로 구분한다.","src":"기출 2021-27"},{"t":"라인형: 안전에 대한 지시 및 전달이 비교적 신속하다.","src":"기출 2021-27"},{"t":"라인형: 소규모(약 100명 이하) 사업장에 주로 활용한다.","src":"보충"},{"t":"라인형 단점: 안전 전문지식과 기술이 부족하고 안전정보 수집이 늦다. 안전 업무가 생산 업무에 밀리기 쉽다.","src":"보충"},{"t":"스태프형: 중규모(약 100~1,000명) 사업장에 주로 활용한다.","src":"보충"},{"t":"스태프형 단점: 권한다툼이나 조정 때문에 라인형보다 통제수속이 복잡하고 시간과 노력이 더 소모된다.","src":"기출 2021-27"},{"t":"스태프형 장점: 안전 전문가가 계획·조사·검토를 맡아 안전 업무의 전문성이 높다.","src":"보충"},{"t":"라인스태프형: 대규모(약 1,000명 이상) 사업장에 주로 활용한다. 라인의 명령 계통과 스태프의 전문 지원을 함께 쓴다.","src":"보충"},{"t":"라인스태프형 단점: 명령 계통과 조언·권고적 참여가 혼돈되기 쉽다.","src":"기출 2021-27"}]},{"머리":"안전관리 활동의 효과","줄":[{"t":"안전관리: 생산성의 향상과 손실(Loss)의 최소화를 위하여, 비능률적 요소인 사고가 발생하지 않는 상태를 유지하기 위한 활동이다.","src":"기출 2024-31"},{"t":"안전관리 활동의 긍정적 효과: 근로자의 사기 진작, 생산성 향상, 신뢰성(사회적 신뢰성) 유지 및 확보, 비용 절감, 이윤 증대.","src":"기출 2023-29 | 기출 2024-31"},{"t":"손실비용 증가는 안전관리 활동의 긍정적 효과가 아니다.","src":"기출 2023-29"},{"t":"생산시설의 고급화 및 다양화는 안전관리의 생산성 측면 효과로 출제되지 않았다(옳지 않은 것으로 출제).","src":"기출 2024-31"}]},{"머리":"리스크 관리 용어","줄":[{"t":"리스크 매트릭스(Risk matrix): 가능성과 결과에 대한 범위를 구분하여 리스크 등급을 표시하고, 리스크 우선순위를 정하기 위한 도구.","src":"기출 2022-26"},{"t":"같은 지침의 다른 용어로 출제된 선지: 리스크 통합(Risk aggregation), 리스크 프로파일(Risk profile), 리스크 수준 판정(Risk evaluation), 리스크 기준(Risk criteria).","src":"기출 2022-26"},{"t":"리스크 기준(Risk criteria): 리스크의 중요도를 평가하는 데 쓰는 기준.","src":"보충(원문 미확인)"},{"t":"리스크 수준 판정(Risk evaluation): 리스크 분석 결과를 리스크 기준과 비교하여 리스크와 그 크기가 허용 가능한지 판정하는 과정.","src":"보충(원문 미확인)"},{"t":"리스크 프로파일(Risk profile): 리스크 집합에 대한 기술.","src":"보충(원문 미확인)"}]},{"머리":"위험성과 유해·위험요인 정의","줄":[{"t":"유해ㆍ위험요인: 유해ㆍ위험을 일으킬 잠재적 가능성이 있는 것의 고유한 특징이나 속성.","src":"사업장 위험성평가에 관한 지침 제3조"},{"t":"위험성: 유해ㆍ위험요인이 사망, 부상 또는 질병으로 이어질 수 있는 가능성과 중대성 등을 고려한 위험의 정도.","src":"사업장 위험성평가에 관한 지침 제3조"}]}],"함정":[{"x":"라인형은 1,000명 이상의 대규모 사업장에 주로 활용된다.","o":"라인형은 소규모(약 100명 이하) 사업장에 주로 활용된다. 1,000명 이상 대규모 사업장에는 라인스태프형을 활용한다.","src":"기출 2021-27 | 보충"}]},"안전교육(원리·방법·TWI·OJT/Off JT·교육기관 기준)":{"묶음":[{"머리":"TWI와 기업내 교육훈련","줄":[{"t":"TWI(Training Within Industry)의 교육훈련 내용: 작업방법훈련(JMT), 작업지도훈련(JIT), 인간관계훈련(JRT), 작업안전훈련(JST).","src":"기출 2021-26"},{"t":"작업적응훈련(JAT)은 TWI 교육훈련 내용이 아니다.","src":"기출 2021-26"},{"t":"TWI는 현장 감독자(관리감독자)를 대상으로 하는 훈련이다.","src":"보충"},{"t":"MTP(Management Training Program): 관리자 대상 경영·관리 훈련.","src":"보충"},{"t":"ATP(Administration Training Program): 최고경영자 대상 훈련.","src":"보충"},{"t":"OJT(On the Job Training): 현장이나 직장에서 직속상사가 부하직원에게 일상 업무를 통하여 지식, 기능, 문제해결능력 및 태도 등을 교육 훈련하는 방법. 개별교육에 적합하다.","src":"기출 2023-30"}]},{"머리":"OJT와 Off JT 비교","줄":[{"t":"Off JT가 OJT보다 유리한 점: 다수의 근로자에게 조직적 훈련이 가능하다.","src":"기출 2022-30"},{"t":"Off JT가 OJT보다 유리한 점: 훈련에만 전념할 수 있다.","src":"기출 2022-30"},{"t":"Off JT가 OJT보다 유리한 점: 전문가를 강사로 초청할 수 있다.","src":"기출 2022-30"},{"t":"개개인에 적합한 지도훈련이 가능한 것은 OJT의 장점이다(Off JT의 장점으로 출제되지 않음).","src":"기출 2022-30"},{"t":"OJT 장점: 직장 실정에 맞는 실제적 훈련, 훈련과 업무의 동시 진행, 교육비 절감.","src":"보충"},{"t":"OJT 단점: 전문적인 교육이 어렵고 다수를 동시에 교육하기 어렵다.","src":"보충"}]},{"머리":"교육 방법","줄":[{"t":"강의식: 오래된 전통 교수방법이며 안전지식의 전달방법으로 유용하다.","src":"기출 2023-27"},{"t":"강의식: 시간과 장소의 제약이 비교적 적다.","src":"기출 2023-27"},{"t":"강의식: 수업의 도입이나 초기단계에 적용이 효과적이다.","src":"기출 2023-27"},{"t":"강의식: 많은 인원을 대상으로 교육할 수 있다.","src":"기출 2023-27"},{"t":"강의식은 수강자의 학습참여도가 낮다. 참여도와 적극성·협조성을 높이는 데에는 토의식 등이 효과적이다.","src":"보충"},{"t":"프로그램 학습법: 스스로 자신의 성장과 향상 의욕을 고취하고 주도적으로 학습하는 방법. 필요한 시간에 개인의 관심·흥미·능력·환경에 맞게 수행하며, 학습참여와 내용 선택에서 자율성이 높다.","src":"기출 2025-26"},{"t":"실연법: 학습자가 이미 설명을 듣거나 시범을 보고 알게 된 지식이나 기능을 교육자의 지휘나 감독 아래 직접 연습하거나 적용하는 교육방법.","src":"기출 2026-29"},{"t":"시범법은 교육자가 시범을 보이고, 실연법은 학습자가 직접 해보는 단계다.","src":"보충"},{"t":"심포지엄: 전문가 몇 사람이 발표한 뒤 청중이 질의하는 토의 방식.","src":"보충"},{"t":"브레인스토밍: 타인의 아이디어를 비판하지 않을 것.","src":"기출 2021-41"},{"t":"브레인스토밍: 자유로운 분위기를 조성할 것.","src":"기출 2021-41"},{"t":"브레인스토밍: 다수의 아이디어를 낼 수 있도록 할 것.","src":"기출 2021-41"},{"t":"브레인스토밍: 타인의 아이디어에 내 아이디어를 덧붙여 제시하는 것은 허용한다(금지가 아님).","src":"기출 2021-41"}]},{"머리":"교수법 단계와 TBM","줄":[{"t":"하버드학파 5단계 교수법 순서: 준비(Preparation) → 교시(Presentation) → 연합(Association) → 총괄(Generalization) → 응용(Application).","src":"기출 2024-30"},{"t":"T.B.M(Tool Box Meeting) 5단계 순서: 도입 → 점검 및 정비 → 작업지시 → 위험예측 → 확인.","src":"기출 2025-32"},{"t":"안전교육 3단계: 지식교육 → 기능교육 → 태도교육.","src":"보충"},{"t":"태도교육 내용: 작업동작 및 표준작업방법의 습관화.","src":"기출 2022-27"},{"t":"태도교육 내용: 공구ㆍ보호구 등의 관리 및 취급태도의 확립.","src":"기출 2022-27"},{"t":"태도교육 내용: 작업 전후 점검 및 검사요령의 정확화 및 습관화.","src":"기출 2022-27"},{"t":"태도교육 내용: 작업지시ㆍ전달 등의 언어ㆍ태도의 정확화 및 습관화.","src":"기출 2022-27"},{"t":"작업에 필요한 안전규정 숙지는 태도교육 내용이 아니다(지식교육 성격).","src":"기출 2022-27"}]},{"머리":"학습지도 원리·지도 원칙·평가기준","줄":[{"t":"학습지도원리: 자발성의 원리, 개별화의 원리, 사회화의 원리, 직관의 원리, 목적의 원리, 통합의 원리.","src":"기출 2022-28 | 기출 2025-27"},{"t":"도미노 이론은 학습지도원리가 아니다.","src":"기출 2022-28"},{"t":"개별화의 원리: 학습자가 지니고 있는 각자의 요구와 능력 등에 알맞은 학습활동의 기회를 마련해 주어야 한다.","src":"기출 2025-27"},{"t":"안전교육의 지도원칙: 피교육자 중심 교육, 동기부여, 오관(감각기관) 활용, 기능적 이해.","src":"기출 2024-32"},{"t":"학습 진행은 쉬운 부분에서 어려운 부분으로 한다(어려운 부분에서 쉬운 부분으로가 아님).","src":"기출 2024-32"},{"t":"학습평가의 기본기준 4가지: 타당성, 신뢰성, 객관성, 실용성.","src":"기출 2021-36"},{"t":"주관성은 학습평가 기본기준이 아니다.","src":"기출 2021-36"}]},{"머리":"법정 안전보건교육 시간: 근로자","줄":[{"t":"정기교육: 사무직 종사 근로자는 매반기 6시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"정기교육: 판매업무에 직접 종사하는 근로자는 매반기 6시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"정기교육: 판매업무 직접 종사 근로자 외의 근로자는 매반기 12시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"채용 시 교육: 일용근로자 및 근로계약기간 1주일 이하인 기간제근로자는 1시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"채용 시 교육: 근로계약기간 1주일 초과 1개월 이하인 기간제근로자는 4시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"채용 시 교육: 그 밖의 근로자는 8시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"작업내용 변경 시 교육: 일용근로자 및 1주일 이하 기간제근로자는 1시간 이상, 그 밖의 근로자는 2시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"특별교육: 일용근로자 및 1주일 이하 기간제근로자는 2시간 이상(별표 5 제1호라목 제39호 제외).","src":"산업안전보건법 시행규칙 별표 4"},{"t":"특별교육: 일용근로자 및 1주일 이하 기간제근로자 중 제39호(타워크레인 신호업무) 작업 종사자는 8시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"특별교육: 그 밖의 근로자는 16시간 이상(최초 작업 종사 전 4시간 이상 실시하고 12시간은 3개월 이내에서 분할 실시 가능). 단기간 작업 또는 간헐적 작업은 2시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"건설업 기초안전ㆍ보건교육: 건설 일용근로자 4시간 이상.","src":"산업안전보건법 시행규칙 별표 4 | 기출 2026-27"},{"t":"건설업 기초안전보건교육 내용: 건설공사의 종류 및 시공 절차 1시간, 산업재해 유형별 위험요인 및 안전보건조치 2시간, 안전보건관리체제 현황 및 근로자 권리ㆍ의무 1시간.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"교육시간을 2분의 1 이상으로 줄일 수 있는 경우: 영 별표 1 제1호에 따른 사업, 상시근로자 50명 미만의 도매업·숙박 및 음식점업.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"일용근로자가 채용 시·특별교육을 받은 날 이후 1주일 동안 같은 사업장에서 같은 업무의 일용근로자로 다시 종사하면 이미 받은 교육을 면제한다.","src":"산업안전보건법 시행규칙 별표 4"}]},{"머리":"법정 안전보건교육 시간: 관리감독자·관리자·기타","줄":[{"t":"관리감독자 정기교육: 연간 16시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"관리감독자 채용 시 교육: 8시간 이상.","src":"산업안전보건법 시행규칙 별표 4 | 기출 2026-27"},{"t":"관리감독자 작업내용 변경 시 교육: 2시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"관리감독자 특별교육: 16시간 이상(최초 작업 종사 전 4시간 이상, 12시간은 3개월 이내 분할 가능). 단기간·간헐적 작업은 2시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"안전보건관리책임자: 신규 6시간 이상, 보수 6시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"안전관리자 및 안전관리전문기관 종사자: 신규 34시간 이상, 보수 24시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"보건관리자 및 보건관리전문기관 종사자: 신규 34시간 이상, 보수 24시간 이상.","src":"산업안전보건법 시행규칙 별표 4 | 기출 2026-27"},{"t":"건설재해예방전문지도기관 종사자: 신규 34시간 이상, 보수 24시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"석면조사기관 종사자: 신규 34시간 이상, 보수 24시간 이상.","src":"산업안전보건법 시행규칙 별표 4 | 기출 2026-27"},{"t":"안전보건관리담당자: 신규교육 없음(-), 보수 8시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"안전검사기관·자율안전검사기관 종사자: 신규 34시간 이상, 보수 24시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"검사원 성능검사 교육: 28시간 이상.","src":"산업안전보건법 시행규칙 별표 4"},{"t":"특수형태근로종사자: 최초 노무제공 시 교육 2시간 이상(단기간·간헐적 작업은 1시간 이상, 특별교육을 실시했으면 면제). 특별교육은 16시간 이상(단기간·간헐적 작업 2시간 이상).","src":"산업안전보건법 시행규칙 별표 4"}]},{"머리":"교육내용(정기·채용 시)","줄":[{"t":"근로자 정기교육 내용: 산업안전 및 산업재해 예방(화재ㆍ폭발 사고 발생 시 대피 포함), 산업보건 및 건강장해 예방(폭염ㆍ한파작업 응급조치 포함), 위험성 평가, 건강증진 및 질병 예방, 유해ㆍ위험 작업환경 관리, 산업안전보건법령 및 산업재해보상보험 제도, 직무스트레스 예방 및 관리, 직장 내 괴롭힘ㆍ고객의 폭언 등으로 인한 건강장해 예방 및 관리.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"채용 시·작업내용 변경 시 교육 내용: 산업안전 및 산업재해 예방, 산업보건 및 건강장해 예방, 위험성 평가, 산업안전보건법령 및 산재보험 제도, 직무스트레스, 직장 내 괴롭힘ㆍ고객의 폭언, 기계ㆍ기구의 위험성과 작업의 순서 및 동선, 작업 개시 전 점검, 정리정돈 및 청소, 사고 발생 시 긴급조치, 물질안전보건자료.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"안전관리자 신규과정 내용: 산업안전보건법령, 산업안전보건개론, 인간공학 및 산업심리, 안전보건교육방법, 재해 발생 시 응급처치, 안전점검ㆍ평가 및 재해 분석기법, 안전기준 및 개인보호구 등 분야별 재해예방 실무, 산업안전보건관리비 계상 및 사용기준, 작업환경 개선 등 산업위생, 무재해운동 추진기법 및 실무, 위험성평가, 그 밖의 직무 향상 사항.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"안전보건관리책임자 신규과정: 관리책임자의 책임과 직무, 산업안전보건법령 및 안전ㆍ보건조치. 보수과정: 산업안전ㆍ보건정책, 자율안전ㆍ보건관리.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"안전보건관리담당자 보수과정: 위험성평가, 안전ㆍ보건교육방법, 사업장 순회점검 및 지도, 기계ㆍ기구의 적격품 선정, 산업재해 통계의 유지ㆍ관리 및 조사, 그 밖의 직무 향상 사항.","src":"산업안전보건법 시행규칙 별표 5"}]},{"머리":"안전보건교육규정(고시)","줄":[{"t":"집체교육: 교육 전용시설 등 교육에 적합한 시설(생산시설·근무장소 제외)에서 강의, 발표, 토의, 세미나, 체험ㆍ실습 방식 등으로 실시하는 교육.","src":"안전보건교육규정 제2조"},{"t":"현장교육: 사업장의 생산시설 또는 근무장소에서 실시하는 교육(작업 전ㆍ후 단시간 TBM, 위험예지훈련 포함).","src":"안전보건교육규정 제2조 | 기출 2024-26"},{"t":"인터넷 원격교육: 정보통신매체를 활용하여 교육이 실시되고 훈련생관리 등이 웹상으로 이루어지는 교육.","src":"안전보건교육규정 제2조 | 기출 2024-26"},{"t":"비대면 실시간교육: 정보통신매체를 활용하여 강사와 교육생이 쌍방향으로 실시간 소통하면서 이루어지는 교육.","src":"안전보건교육규정 제2조 | 기출 2024-26"},{"t":"전문화교육: 직무교육기관이 근로자등 및 직무교육대상자의 전문성을 높이기 위해 업종 또는 관련 분야별로 개발ㆍ운영하는 교육.","src":"안전보건교육규정 제2조 | 기출 2024-26"},{"t":"안전보건관리담당자 양성교육: 안전보건관리담당자 자격을 부여하기 위한 안전보건교육.","src":"안전보건교육규정 제2조"},{"t":"안전관리자 양성교육: 안전관리자 자격을 부여하기 위한 교육.","src":"안전보건교육규정 제2조"},{"t":"교육형태는 집체교육·현장교육·인터넷 원격교육·비대면 실시간교육 중 어느 하나 또는 혼합한 방식으로 한다.","src":"안전보건교육규정 제3조 | 기출 2024-33"},{"t":"특별교육은 총 교육시간의 3분의 2 이상을 집체교육, 현장교육 또는 비대면 실시간교육으로 해야 한다.","src":"안전보건교육규정 제3조 | 기출 2026-28"},{"t":"관리감독자 정기교육은 해당연도 총 교육시간의 2분의 1 이상을 집체교육, 현장교육 또는 비대면 실시간교육으로 해야 한다.","src":"안전보건교육규정 제3조"},{"t":"직무교육은 총 교육시간의 3분의 2 이상을 집체교육, 현장교육 또는 비대면 실시간교육으로 해야 한다.","src":"안전보건교육규정 제15조 | 기출 2024-33"},{"t":"특별교육 18시간 배분 판단: 집체+현장+비대면 실시간 합계가 12시간 이상이어야 적합하다(예: 4+4+4, 2+2+8은 적합, 2+2+6, 3+3+4는 부적합).","src":"안전보건교육규정 제3조 | 기출 2026-28"},{"t":"안전보건관리담당자 양성교육을 집체교육과 인터넷 원격교육으로 병행할 때 인터넷 원격교육은 총 교육시간의 3분의 1 범위 내.","src":"안전보건교육규정 제23조의5"},{"t":"안전관리자 양성교육을 집체교육과 인터넷 원격교육으로 병행할 때 인터넷 원격교육은 총 교육시간의 3분의 2 범위 내.","src":"안전보건교육규정 제23조의6"},{"t":"건설업 기초안전보건교육은 시설기준에 적합한 강의실에서 집체교육으로 실시한다(체험ㆍ가상실습 포함 시 별도 장소 가능).","src":"안전보건교육규정"},{"t":"근로자안전보건교육기관의 시설 기준: 사무실 연면적 30㎡ 이상, 강의실 연면적 120㎡ 이상이며 의자ㆍ탁자 및 교육용 비품을 갖출 것.","src":"기출 2026-26"}]}],"함정":[{"x":"검사원의 성능검사 교육은 16시간 이상이다.","o":"검사원 성능검사 교육은 28시간 이상이다.","src":"산업안전보건법 시행규칙 별표 4 | 기출 2026-27"},{"x":"수강자의 학습참여도가 높고 적극성과 협조성을 부여하는 데 효과적이다.","o":"강의식은 일방 전달이라 참여도가 낮다. 도입 단계·많은 인원·시간 장소 제약이 적은 점이 강의식의 장점이다.","src":"기출 2023-27 | 보충"},{"x":"\"안전보건관리담당자 양성교육\"이란 안전보건총괄책임자 자격을 부여하기 위한 양성교육을 말한다.","o":"안전보건관리담당자 양성교육은 안전보건관리담당자 자격을 부여하기 위한 안전보건교육이다.","src":"안전보건교육규정 제2조 | 기출 2024-26"}]},"재해조사와 원인분석(절차·4M·5W1H·통계적 분석기법)":{"묶음":[{"머리":"재해조사 절차와 요령","줄":[{"t":"재해조사 과정 순서: 5W1H 원칙에 따른 사실 확인 → 불안전 상태와 불안전 행동에 해당하는 직접 원인 파악 → 4M 모델에 따른 기본 원인 파악 → 근본적 문제점 결정.","src":"기출 2022-37"},{"t":"재해조사 1단계(사실 확인) 활동: 재해 발생 작업의 지휘ㆍ감독 상황 조사, 재해 발생 기계ㆍ설비의 위험방호설비 확인.","src":"기출 2024-35"},{"t":"재해 발생의 직접 원인(불안전 상태·불안전 행동) 판단은 사실 확인 다음 단계다.","src":"기출 2024-35"},{"t":"재해 피해자 구출과 응급조치를 가장 먼저 실시한다.","src":"기출 2024-37"},{"t":"재해 조사를 위하여 현장을 보존하고 촬영 등의 기록을 실시한다.","src":"기출 2024-37"},{"t":"재해 조사 담당 인력에 안전관리자를 포함시킨다.","src":"기출 2024-37"},{"t":"재해 조사는 2차 재해 발생 우려가 없는지 확인한 뒤 가능하면 신속히 실시한다.","src":"기출 2024-37"},{"t":"재해 조사는 재해 발생 현장으로 범위를 한정하지 않는다. 원인 조사는 관련 범위 전체(작업 방법, 관리 상태 등)를 대상으로 한다.","src":"기출 2024-37 | 보충"},{"t":"재해조사 시 유의: 책임추궁보다 재발방지를 우선하는 태도로 조사한다.","src":"기출 2025-45"},{"t":"재해조사 시 유의: 목격자의 추측적인 말은 참고로 한다.","src":"기출 2025-45"},{"t":"재해조사 시 유의: 발생 후 가능한 빨리 현장이 변형되지 않은 상태에서 실시한다.","src":"기출 2025-45"},{"t":"재해조사 시 유의: 조사자는 객관적인 입장에서 공정하게 조사한다(주관적 입장이 아님).","src":"기출 2025-45"},{"t":"재해사례연구 진행 순서: 재해 상황 파악 → 재해와 관계가 있는 사실 및 재해요인으로 알려진 사실의 객관적 확인 → 파악된 사실로부터 문제점 파악 → 재해의 중심이 된 근본적 문제점 결정 후 재해원인 결정 → 동종재해·유사재해의 예방대책 및 실시계획 수립.","src":"기출 2023-44"}]},{"머리":"4M과 5W1H","줄":[{"t":"산업재해 기본 원인 4M: Man(인간), Machine(기계), Media(매체), Management(관리).","src":"기출 2023-35"},{"t":"Method(방법)는 4M에 해당하지 않는다.","src":"기출 2023-35"},{"t":"5W1H: 누가(Who), 언제(When), 어디서(Where), 무엇을(What), 왜(Why), 어떻게(How).","src":"보충"}]},{"머리":"기인물·가해물·사고유형","줄":[{"t":"기인물: 재해의 원인이 된 불안전한 상태에 있는 물체나 장치. 가해물: 직접 사람에게 상해를 입힌 물체. 사고유형: 재해가 발생한 형태(추락, 전도, 충돌, 낙하ㆍ비래, 협착, 감전 등).","src":"보충"},{"t":"사례 판단: 미끄러운 기름이 흘러 있는 복도에서 미끄러져 넘어지며 기계에 머리를 부딪친 재해는 기인물 기름, 가해물 기계, 사고유형 전도다.","src":"기출 2021-31"}]},{"머리":"통계적 원인분석 기법","줄":[{"t":"재해의 통계적 원인분석 방법: 파레토도, 특성요인도, 클로즈분석도, 관리도.","src":"기출 2023-32"},{"t":"소시오메트리도는 집단 내 구성원 사이의 관계를 보는 기법으로 통계적 원인분석 방법에 해당하지 않는다.","src":"기출 2023-32 | 보충"},{"t":"파레토도: 항목별 건수를 큰 순서로 막대로 나타내고 누적 비율선을 겹쳐 중점 관리 항목을 찾는 도표.","src":"보충"},{"t":"특성요인도(어골도): 결과(재해)에 영향을 주는 원인을 계통적으로 나타낸 도표.","src":"보충"},{"t":"클로즈분석(교차분석): 두 개 이상의 요인을 교차시켜 관계를 분석하는 방법.","src":"보충"},{"t":"관리도: 관리 상한선(UCL)·하한선(LCL)을 두고 공정이나 재해율의 변동을 관리하는 도표.","src":"보충"}]},{"머리":"중대재해와 산업재해 보고","줄":[{"t":"중대재해: 사망자 1명 이상 발생한 재해.","src":"산업안전보건법 시행규칙 제3조"},{"t":"중대재해: 3개월 이상의 요양이 필요한 부상자가 동시에 2명 이상 발생한 재해.","src":"산업안전보건법 시행규칙 제3조"},{"t":"중대재해: 부상자 또는 직업성 질병자가 동시에 10명 이상 발생한 재해.","src":"산업안전보건법 시행규칙 제3조"},{"t":"산업재해로 사망자가 발생하거나 3일 이상의 휴업이 필요한 부상·질병이 발생하면, 사업주는 발생일부터 1개월 이내에 별지 제30호서식의 산업재해조사표를 작성하여 관할 지방고용노동관서의 장에게 제출해야 한다.","src":"산업안전보건법 시행규칙 제73조"},{"t":"산업재해조사표에는 근로자대표의 확인을 받아야 하고, 이견이 있으면 그 내용을 첨부한다. 근로자대표가 없으면 재해자 본인의 확인을 받아 제출할 수 있다.","src":"산업안전보건법 시행규칙 제73조"},{"t":"산업재해조사표 항목 연결: 재해정보 - 상해부위는 옳은 연결이다. 사업장정보 - 근무형태, 재해발생 개요 및 원인 - 휴업예상일수는 옳지 않은 연결로 출제됐다.","src":"기출 2026-47"}]}],"함정":[{"x":"빠른 복구를 위해 재해 조사는 재해 발생 현장으로 대상 범위를 한정하여 실시한다.","o":"재해 조사는 현장에 한정하지 않는다. 현장 보존·촬영, 관련자 청취, 작업 방법과 관리 상태 등 관련 범위 전체를 조사한다.","src":"기출 2024-37 | 보충"}]},"재해통계(도수율·강도율·천인율·연천인율·종합재해지수·손실일수)":{"묶음":[{"머리":"재해율 공식","줄":[{"t":"도수율(빈도율, FR) = 재해 건수 ÷ 연 근로시간 수 × 1,000,000.","src":"기출 2021-49 | 기출 2024-36"},{"t":"강도율(SR) = 근로손실일수 ÷ 연 근로시간 수 × 1,000.","src":"기출 2021-49"},{"t":"천인율(연천인율) = 연간 재해자 수 ÷ 연평균 근로자 수 × 1,000.","src":"기출 2024-36 | 보충"},{"t":"연천인율 = 도수율 × 2.4, 도수율 = 연천인율 ÷ 2.4 (연 2,400시간 기준).","src":"보충"},{"t":"평균강도율 = 강도율 ÷ 도수율 × 1,000 (재해 1건당 평균 근로손실일수).","src":"보충"},{"t":"종합재해지수(FSI) = √(도수율 × 강도율).","src":"기출 2026-48 | 기출 2024-36"},{"t":"환산강도율 = 강도율 × 100 (근로자가 평생 근무하는 100,000시간 기준 근로손실일수).","src":"기출 2026-48 | 보충"},{"t":"환산도수율 = 도수율 × 0.1 (평생 근로시간 100,000시간 기준 재해건수).","src":"보충"},{"t":"연 근로시간이 주어지지 않으면 근로자 수 × 2,400시간(1일 8시간 × 300일)으로 계산한다.","src":"기출 2021-49 | 보충"}]},{"머리":"계산 풀이 순서","줄":[{"t":"풀이 순서: ① 연 근로시간 = 근로자 수 × 2,400 ② 도수율 = 건수 ÷ 시간 × 10^6 ③ 강도율 = 손실일수 ÷ 시간 × 10^3.","src":"보충"},{"t":"예: 500명, 연 30건, 손실 120일 → 시간 1,200,000 → 도수율 25, 강도율 0.1.","src":"기출 2021-49"},{"t":"역산: 천인율 1.6, 근로자 2,500명이면 재해자(건수) = 1.6 × 2,500 ÷ 1,000 = 4. 도수율 0.8이면 연 근로시간 = 4 ÷ 0.8 × 10^6 = 5,000,000. 강도율 1.2이면 손실일수 = 1.2 × 5,000,000 ÷ 1,000 = 6,000일.","src":"기출 2022-42"},{"t":"종합재해지수·환산강도율 계산: 도수율 5, 강도율 5 → FSI = √25 = 5, 환산강도율 = 5 × 100 = 500.","src":"기출 2026-48"},{"t":"강도율 문제(2025-47): 근로손실일수 = 사망 7,500일 + 장해등급별 일수 × 인원 + 휴업일수 × 연간근무일수/365. 연 근로시간 = 400 × 2,400 = 960,000.","src":"기출 2025-47 | 보충"}]},{"머리":"근로손실일수 산정","줄":[{"t":"사망 시 근로손실일수는 7,500일이다.","src":"기출 2024-36 | 기출 2026-49"},{"t":"사망 7,500일의 근거: 평균 사망 연령 30세에서 근로가능 연령 55세까지 25년 × 연 300일.","src":"보충"},{"t":"신체장해자 1등급: 근로손실일수 7,500일.","src":"기출 2026-49"},{"t":"신체장해자 3등급: 근로손실일수 5,500일(2026-49 보기에서 옳은 것으로 출제).","src":"기출 2026-49"},{"t":"신체장해자 9등급: 근로손실일수 1,000일.","src":"기출 2026-49"},{"t":"신체장해자 13등급: 근로손실일수 100일.","src":"기출 2026-49"},{"t":"일반 교재의 장해등급 표: 1~3급 7,500, 4급 5,500, 5급 4,000, 6급 3,000, 7급 2,200, 8급 1,500, 9급 1,000, 10급 600, 11급 400, 12급 200, 13급 100, 14급 50. 2026-49 보기의 3급(5,500)·7급(2,200)과 일부 달라 출제 기준표 확인이 필요하다.","src":"보충(원문 미확인)"},{"t":"일시 전노동불능(휴업)은 휴업일수 × 연간근로일수/365로 환산한다.","src":"보충"}]},{"머리":"안전성 비교","줄":[{"t":"안전성 비교(Safety T-score)는 현재의 안전성을 과거와 비교한 것이다.","src":"기출 2024-36"},{"t":"Safety T-score가 -2 이하이면 과거에 비해 안전성이 개선된 것이다.","src":"기출 2024-36"},{"t":"Safety T-score가 +2 이상이면 과거보다 나빠진 것이고, -2~+2는 차이가 없다고 본다.","src":"보충"},{"t":"Safety T-score = (현재 도수율 - 과거 도수율) ÷ √(과거 도수율 ÷ 현재 총 근로시간 × 10^6).","src":"보충"}]}],"함정":[{"x":"강도율 계산 시 사망 재해의 경우 10,000일의 근로손실일수를 산정한다.","o":"사망 재해의 근로손실일수는 7,500일이다.","src":"기출 2024-36 | 기출 2026-49"},{"x":"도수율(빈도율)은 연근로시간 100,000시간당 재해 발생 건수를 의미한다.","o":"도수율은 연근로시간 1,000,000시간당 재해 발생 건수다.","src":"기출 2024-36"},{"x":"재해율(천인율)은 연평균 근로자 1,000명당 재해 발생 건수를 의미한다.","o":"천인율은 연평균 근로자 1,000명당 재해자 수를 뜻한다(건수가 아님).","src":"기출 2024-36 | 보충"},{"x":"종합재해지수(FSI)는 도수율과 강도율을 곱한 값이다.","o":"종합재해지수는 도수율과 강도율을 곱한 값의 제곱근이다.","src":"기출 2024-36"},{"x":"신체장해자 7등급 경우, 근로손실일수는 2,200일이다.","o":"출제 오답(2026-49 기준 바른 수치 미확인)","src":"기출 2026-49"}]},"재해이론(하인리히·버드 등 사고연쇄이론과 재해손실비)":{"묶음":[{"머리":"하인리히","줄":[{"t":"하인리히의 법칙: 330건의 사고 중 중상 또는 사망 1건, 경상 29건, 무상해 사고 300건(1 : 29 : 300).","src":"기출 2021-28"},{"t":"하인리히는 재해손실비용의 직접비와 간접비 비율을 약 1 : 4로 제시했다.","src":"기출 2022-38"},{"t":"하인리히 도미노(사고 연쇄) 5단계: 사회적 환경 및 유전적 요소 → 개인적 결함 → 불안전 행동 및 불안전 상태 → 사고 → 상해.","src":"보충"},{"t":"하인리히는 연쇄 중 3단계(불안전 행동·불안전 상태)를 제거하면 사고와 상해로 이어지지 않는다고 보았다.","src":"보충"},{"t":"하인리히 사고예방 원리 5단계: 안전조직 → 사실의 발견 → 분석ㆍ평가 → 시정방법의 선정 → 시정책의 적용.","src":"보충"},{"t":"직접비: 법에 의한 산재보상비(요양·휴업·장해·유족·장의 등). 간접비: 인적 손실, 물적 손실, 생산 손실, 특수 손실 등.","src":"보충"}]},{"머리":"버드·아담스·시몬즈·콤페스","줄":[{"t":"버드의 재해 구성비율은 1 : 10 : 30 : 600이다(중상 1, 경상 10, 물적 손실 30, 무상해ㆍ무손실 사고 600).","src":"기출 2024-28 | 기출 2022-38"},{"t":"버드는 1건의 중상이 발생할 때 10건의 경상, 300건의 아차 사고가 발생한다고 하지 않았다(그렇게 설명한 보기는 옳지 않음).","src":"기출 2022-38"},{"t":"버드의 신 도미노: 통제의 부족(관리) → 기본 원인(기원) → 직접 원인(징후) → 사고(접촉) → 상해(손해).","src":"보충"},{"t":"아담스: 관리구조 → 작전적 에러 → 전술적 에러 → 사고 → 상해의 연쇄를 제시했다.","src":"보충"},{"t":"시몬즈(Simonds): 평균치법을 적용해 재해손실비용을 산출했다.","src":"기출 2022-38"},{"t":"시몬즈 방식: 총 재해비용 = 산재보험비용 + 비보험비용.","src":"기출 2023-48"},{"t":"시몬즈 방식: 비보험비용 = 휴업상해건수×A + 통원상해건수×B + 응급조치건수×C + 무상해 사고건수×D (A·B·C·D는 장해 정도별 비보험비용의 평균치).","src":"기출 2023-48"},{"t":"콤페스(P. Compes)는 재해손실비 산정에서 개별비용 산정 방식을 제시한 학자로 선지에 나왔다.","src":"보충(원문 미확인)"}]},{"머리":"휴의 요인론과 스위스치즈 모델","줄":[{"t":"휴의 이론 중 인위적 요인: 무리한 행동, 안전작업에 대한 소홀, 신체적 특성을 고려하지 못한 작업배치, 자동화 기기와 일반기계의 속도차이, 단순작업의 권태감·무력감, 작업자 신체 기능·정보처리능력의 변화로 스트레스가 증가해 재해가 발생할 수 있다.","src":"기출 2025-31"},{"t":"휴의 이론 선지 요인: 심리적 요인, 기계적 요인, 인위적 요인, 기술적 요인, 환경적 요인.","src":"기출 2025-31"},{"t":"스위스치즈 사고인과모델에서 안전 사고에 관여하는 원인: 작업자의 실수, 실수를 유발하는 작업환경, 부적절한 인터페이스 설계, 폐쇄적인 조직문화.","src":"기출 2026-30"},{"t":"천재지변에 의한 사고는 스위스치즈 모델의 관여 원인으로 출제되지 않았다(옳지 않은 것).","src":"기출 2026-30"},{"t":"스위스치즈 모델: 여러 방어층의 구멍(능동적 실패와 잠재적 조건)이 한 줄로 겹칠 때 사고가 발생한다는 모델.","src":"보충"}]}],"함정":[]},"위험성평가(지침·절차·실시주체·인정기준·기법)":{"묶음":[{"머리":"법 제36조 위험성평가","줄":[{"t":"위험성평가: 사업주가 건설물, 기계ㆍ기구ㆍ설비, 원재료, 가스, 증기, 분진, 근로자의 작업행동 또는 그 밖의 업무로 인한 유해ㆍ위험 요인을 찾아내어, 사망ㆍ부상ㆍ질병으로 이어질 수 있는 위험성의 크기가 허용 가능한 수준인지 결정하고, 위험성을 줄이기 위한 개선대책을 수립하고 이행하는 것.","src":"산업안전보건법 제36조"},{"t":"사업주는 위험성평가 시 고용노동부령으로 정하는 바에 따라 해당 사업장의 근로자를 참여시켜야 한다.","src":"산업안전보건법 제36조"},{"t":"사업주는 근로자대표가 요구하면 위험성평가 시 근로자대표를 참여시켜야 한다.","src":"산업안전보건법 제36조"},{"t":"사업주는 위험성평가 관련 사항을 안전보건교육, 설명회, 사업장 게시, 서면 또는 전자적 방법 등으로 근로자에게 알려야 한다. 중대재해로 이어질 수 있는 요인은 작업 전 안전점검회의 등으로 상시 주지시키도록 노력한다.","src":"산업안전보건법 제36조"},{"t":"사업주는 위험성평가 결과를 고용노동부령으로 정하는 바에 따라 기록하여 보존하여야 한다.","src":"산업안전보건법 제36조"}]},{"머리":"실시주체·대상·근로자 참여","줄":[{"t":"위험성평가는 사업주가 스스로 실시한다.","src":"사업장 위험성평가에 관한 지침 제5조"},{"t":"작업의 일부 또는 전부를 도급에 의하여 행하는 사업은 도급사업주와 수급사업주가 각각 위험성평가를 실시한다.","src":"사업장 위험성평가에 관한 지침 제5조 | 기출 2026-34"},{"t":"도급사업주는 수급사업주가 실시한 위험성평가 결과를 검토하여 도급사업주가 개선할 사항이 있으면 개선한다.","src":"사업장 위험성평가에 관한 지침 제5조"},{"t":"평가 대상: 업무 중 근로자에게 노출되었거나 노출될 것이 합리적으로 예견 가능한 모든 유해ㆍ위험요인. 매우 경미한 부상·질병만 초래할 것이 명백한 요인은 제외할 수 있다.","src":"사업장 위험성평가에 관한 지침 제5조의2"},{"t":"아차사고를 확인한 경우 그 사고를 일으킨 유해ㆍ위험요인을 평가 대상에 포함시켜야 한다.","src":"사업장 위험성평가에 관한 지침 제5조의2"},{"t":"중대재해가 발생하면 지체 없이 중대재해 원인 요인에 대해 수시 위험성평가를 하고, 그 밖의 요인은 재검토한다.","src":"사업장 위험성평가에 관한 지침 제5조의2"},{"t":"근로자 참여 사항 1: 위험성 수준 판단 기준을 마련하고 허용 가능한 위험성 수준을 정하거나 변경하는 경우.","src":"사업장 위험성평가에 관한 지침 제6조"},{"t":"근로자 참여 사항 2: 해당 사업장의 유해ㆍ위험요인을 파악하는 경우.","src":"사업장 위험성평가에 관한 지침 제6조 | 기출 2025-41"},{"t":"근로자 참여 사항 3: 유해ㆍ위험요인의 위험성이 허용 가능한 수준인지 결정하는 경우.","src":"사업장 위험성평가에 관한 지침 제6조 | 기출 2025-41"},{"t":"근로자 참여 사항 4: 위험성 감소대책을 수립하여 실행하는 경우.","src":"사업장 위험성평가에 관한 지침 제6조 | 기출 2025-41"},{"t":"근로자 참여 사항 5: 위험성 감소대책 실행 여부를 확인하는 경우.","src":"사업장 위험성평가에 관한 지침 제6조 | 기출 2025-41"}]},{"머리":"방법·체제","줄":[{"t":"안전보건관리책임자 등 사업 실시를 총괄 관리하는 사람에게 위험성평가의 실시를 총괄 관리하게 한다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"안전관리자, 보건관리자 등은 위험성평가 실시에 관하여 안전보건관리책임자를 보좌하고 지도ㆍ조언한다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"기계ㆍ기구, 설비 등의 위험성평가에는 해당 분야 전문 지식을 갖춘 사람을 참여시킨다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"안전ㆍ보건관리자 선임의무가 없는 사업장은 보좌 업무를 수행할 사람을 지정하는 등 체제를 구축한다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"사업주는 위험성평가 담당자 등에게 필요한 교육을 실시한다. 외부 교육을 받았거나 관련학문 전공자는 필요한 부분만 교육하거나 생략할 수 있다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"위험성평가 시 산업안전ㆍ보건 전문가 또는 전문기관의 컨설팅을 받을 수 있다.","src":"사업장 위험성평가에 관한 지침 제7조"},{"t":"위험성평가를 실시한 것으로 인정하는 제도: 위험성평가 방법을 적용한 안전ㆍ보건진단(법 제47조).","src":"사업장 위험성평가에 관한 지침 제7조 | 기출 2026-35"},{"t":"위험성평가를 실시한 것으로 인정하는 제도: 공정안전보고서(공정위험성 평가서가 최대 4년 범위 이내에서 정기적으로 작성된 경우에 한함).","src":"사업장 위험성평가에 관한 지침 제7조 | 기출 2026-35"},{"t":"위험성평가를 실시한 것으로 인정하는 제도: 근골격계부담작업 유해요인조사(안전보건규칙 제657조~제662조).","src":"사업장 위험성평가에 관한 지침 제7조 | 기출 2026-35"},{"t":"밀폐공간작업 프로그램의 수립ㆍ시행은 위험성평가를 실시한 것으로 인정하는 제도로 출제되지 않았다.","src":"기출 2026-35"},{"t":"위험성평가 방법: 위험 가능성과 중대성을 조합한 빈도ㆍ강도법, 체크리스트(Checklist)법, 위험성 수준 3단계(저ㆍ중ㆍ고) 판단법, 핵심요인 기술(One Point Sheet)법, 그 외 규칙 제50조제1항제2호 각 목의 방법.","src":"사업장 위험성평가에 관한 지침 제7조"}]},{"머리":"절차와 사전준비","줄":[{"t":"위험성평가 절차: 사전준비 → 유해ㆍ위험요인 파악 → 위험성 결정 → 위험성 감소대책 수립 및 실행 → 위험성평가 실시내용 및 결과에 관한 기록 및 보존.","src":"사업장 위험성평가에 관한 지침 제8조"},{"t":"현행 지침은 상시근로자 5인 미만 사업장(건설공사 1억원 미만)이 사전준비 절차를 생략할 수 있다(2021 기출 당시에는 상시근로자 20명 미만(공사금액 20억원 미만)에서 '위험성의 추정' 절차를 생략할 수 있었음).","src":"사업장 위험성평가에 관한 지침 제8조 | 기출 2021-34"},{"t":"위험성평가 실시규정에 포함할 사항: 평가의 목적 및 방법.","src":"사업장 위험성평가에 관한 지침 제9조 | 기출 2022-31"},{"t":"위험성평가 실시규정에 포함할 사항: 평가담당자 및 책임자의 역할.","src":"사업장 위험성평가에 관한 지침 제9조 | 기출 2022-31"},{"t":"위험성평가 실시규정에 포함할 사항: 평가시기 및 절차.","src":"사업장 위험성평가에 관한 지침 제9조 | 기출 2022-31"},{"t":"위험성평가 실시규정에 포함할 사항: 근로자에 대한 참여ㆍ공유방법 및 유의사항(주지방법 및 유의사항).","src":"사업장 위험성평가에 관한 지침 제9조 | 기출 2022-31 | 기출 2024-50"},{"t":"위험성평가 실시규정에 포함할 사항: 결과의 기록ㆍ보존.","src":"사업장 위험성평가에 관한 지침 제9조 | 기출 2024-50"},{"t":"인정심사위원회의 구성ㆍ운영, 위험성평가 인정신청서 작성방법은 실시규정 포함 사항이 아니다.","src":"기출 2022-31 | 기출 2024-50"},{"t":"실시규정은 최초 위험성평가 시 작성하고 지속적으로 관리한다.","src":"사업장 위험성평가에 관한 지침 제9조"},{"t":"위험성평가 전에 확정할 사항: 위험성의 수준과 그 수준을 판단하는 기준, 허용 가능한 위험성의 수준(법에서 정한 기준 이상으로 정함).","src":"사업장 위험성평가에 관한 지침 제9조"},{"t":"사전조사 안전보건정보: 작업표준ㆍ작업절차, 기계ㆍ기구ㆍ설비 사양서와 MSDS, 공정 흐름과 작업 주변 환경, 혼재작업 정보(도급), 재해사례ㆍ재해통계, 작업환경측정ㆍ건강진단 결과, 그 밖의 참고 자료.","src":"사업장 위험성평가에 관한 지침 제9조"},{"t":"유해ㆍ위험요인 파악 방법(하나 이상, 특별한 사정이 없으면 순회점검 포함): 사업장 순회점검, 근로자 상시 제안, 설문조사ㆍ인터뷰 등 청취조사, MSDS·작업환경측정결과·특수건강진단결과 등 자료, 안전보건 체크리스트, 그 밖의 사업장 특성에 적합한 방법.","src":"사업장 위험성평가에 관한 지침 제10조"},{"t":"위험성 결정: 파악된 요인이 근로자에게 노출되었을 때의 위험성을 사전에 정한 기준으로 판단하고, 허용 가능한 위험성 수준인지 결정한다.","src":"사업장 위험성평가에 관한 지침 제11조"},{"t":"위험성 감소대책 우선순위: ① 위험한 작업의 폐지ㆍ변경, 유해ㆍ위험물질 대체, 설계·계획 단계의 위험성 제거·저감 ② 연동장치, 환기장치 등 공학적 대책 ③ 작업절차서 정비 등 관리적 대책 ④ 개인용 보호구 사용.","src":"사업장 위험성평가에 관한 지침 제12조"},{"t":"감소대책 실행 후 허용 가능한 수준인지 확인하고, 내려오지 않으면 추가 대책을 수립ㆍ실행한다. 중대재해 우려가 있고 실행에 시간이 걸리면 즉시 잠정조치를 강구한다.","src":"사업장 위험성평가에 관한 지침 제12조"},{"t":"위험성평가 결과 공유: 근로자가 종사하는 작업의 유해ㆍ위험요인, 위험성 결정 결과, 감소대책과 실행계획 및 실행 여부, 근로자가 준수·주의할 사항을 게시, 주지 등의 방법으로 알린다.","src":"사업장 위험성평가에 관한 지침 제13조"},{"t":"기록: 사전조사한 안전보건정보 등을 포함한다.","src":"사업장 위험성평가에 관한 지침 제14조"}]},{"머리":"실시 시기","줄":[{"t":"최초 위험성평가: 사업이 성립된 날(건설업은 실착공일)부터 1개월이 되는 날까지 실시에 착수한다. 1개월 미만 작업·공사는 개시 후 지체 없이 실시한다.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"수시 위험성평가 사유: 건설물의 설치ㆍ이전ㆍ변경 또는 해체.","src":"사업장 위험성평가에 관한 지침 제15조 | 기출 2022-36"},{"t":"수시 위험성평가 사유: 기계ㆍ기구, 설비, 원재료 등의 신규 도입 또는 변경.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"수시 위험성평가 사유: 건설물, 기계ㆍ기구, 설비 등의 정비 또는 보수(주기적ㆍ반복적 작업으로 이미 평가한 경우 제외).","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"수시 위험성평가 사유: 작업방법 또는 작업절차의 신규 도입 또는 변경.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"수시 위험성평가 사유: 중대산업사고 또는 산업재해(휴업 이상의 요양을 요하는 경우에 한정) 발생. 이 경우 재해발생 작업을 대상으로 작업을 재개하기 전에 실시한다.","src":"사업장 위험성평가에 관한 지침 제15조 | 기출 2022-36"},{"t":"수시 위험성평가 사유: 그 밖에 사업주가 필요하다고 판단한 경우.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"정기 재검토: 최초 평가 결과의 적정성을 1년마다 정기적으로 재검토하고, 같은 기간의 수시평가 결과도 함께 재검토한다.","src":"사업장 위험성평가에 관한 지침 제15조 | 기출 2022-36"},{"t":"정기 재검토 고려사항: 기계ㆍ기구ㆍ설비의 기간 경과에 의한 성능 저하, 근로자 교체 등에 따른 지식·경험의 변화, 새로운 안전ㆍ보건 지식의 습득, 현재 수립된 감소대책의 유효성.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"상시 위험성평가 인정: 매월 1회 이상 제안제도·아차사고 확인·순회점검으로 요인 발굴 및 대책 수립ㆍ실행, 매주 책임자·관리자 중심 논의ㆍ공유, 매 작업일 작업 전 안전점검회의로 주지하면 수시·정기평가를 실시한 것으로 본다.","src":"사업장 위험성평가에 관한 지침 제15조"},{"t":"기출 2022 당시 보기: 위험성평가는 최초평가 및 수시평가, 정기평가로 구분하며, 최초평가·정기평가는 전체작업을 대상으로 한다(현행 지침 문구는 제15조 기준).","src":"기출 2022-36"}]},{"머리":"위험성평가 인정","줄":[{"t":"인정 신청 대상: 상시 근로자 100명 미만 사업장(건설공사 제외), 총 공사금액 120억원(토목공사 150억원) 미만 건설공사.","src":"사업장 위험성평가에 관한 지침 제16조"},{"t":"인정 신청은 위험성평가 인정신청서를 관할 공단 광역본부장ㆍ지역본부장ㆍ지사장에게 제출한다.","src":"사업장 위험성평가에 관한 지침 제16조"},{"t":"인정 신청 불가: 인정 취소일부터 1년이 경과하지 않은 사업장, 최근 1년 이내에 제22조제1항 제2~4호 사유가 있는 사업장.","src":"사업장 위험성평가에 관한 지침 제16조"},{"t":"도급 사업장은 도급사업장의 사업주가 수급사업장을 일괄하여 인정을 신청한다.","src":"사업장 위험성평가에 관한 지침 제16조"},{"t":"인정심사 항목: 사업주의 관심도, 위험성평가 실행수준, 구성원의 참여 및 이해 수준, 재해발생 수준.","src":"사업장 위험성평가에 관한 지침 제17조"},{"t":"현장심사: 직전일 기준 최초인정은 최근 1년, 재인정은 최근 3년 이내 실시한 위험성평가를 대상으로 한다. 결과는 인정심사위원회에 보고한다.","src":"사업장 위험성평가에 관한 지침 제17조"},{"t":"인정심사위원회: 공단 광역본부장ㆍ지역본부장ㆍ지사장이 위원장, 지방고용노동관서 산재예방지도과장이 당연직 위원, 5명 이상 10명 이하로 구성하고 외부 위원은 위원장 제외 위원 수의 2분의 1 이상.","src":"사업장 위험성평가에 관한 지침 제18조"},{"t":"인정 심의사항: 인정 여부, 인정취소 여부, 이의신청 심사, 심사항목·기준 개정 건의, 그 밖에 위원장이 회의에 부치는 사항.","src":"사업장 위험성평가에 관한 지침 제18조"},{"t":"인정 결정: 현장심사 완료일부터 1개월 이내에 인정심사위원회 심의ㆍ의결을 거친다.","src":"사업장 위험성평가에 관한 지침 제19조"},{"t":"인정 기준: 평가점수가 100점 만점에 항목별 70점 미달이 없고 종합점수가 90점 이상.","src":"사업장 위험성평가에 관한 지침 제19조"},{"t":"인정 유효기간: 인정 결정일부터 3년.","src":"사업장 위험성평가에 관한 지침 제19조"},{"t":"재인정 신청은 유효기간 만료일 3개월 전부터 할 수 있고, 재인정 유효기간은 이전 만료일 다음날부터 새로 계산한다.","src":"사업장 위험성평가에 관한 지침 제20조"},{"t":"인정 종합점수 가중치: 사업주의 관심도 10%, 실행수준 60%, 구성원 참여·이해 25%, 재해발생 5%.","src":"사업장 위험성평가에 관한 지침 별표"},{"t":"인정 취소 사유: 거짓·부정 인정, 인정기간 중 중대재해(사망 1명 이상 등) 발생, 3일 이상 휴업 부상을 동반한 중대산업사고, 재해 발생 공표 사업장, 사후점검 거부 또는 인정기준 미충족, 자진 취소 요청, 그 밖의 필요 사유.","src":"사업장 위험성평가에 관한 지침 제22조"},{"t":"인정사업장 사후점검: 인정기간 중 1회 이상 실시할 수 있다.","src":"사업장 위험성평가에 관한 지침 제21조"},{"t":"인정사업장에는 인정 유효기간 동안 사업장 안전보건 감독을 유예할 수 있다.","src":"사업장 위험성평가에 관한 지침 제27조"}]},{"머리":"사고 피해예측 기법","줄":[{"t":"사고 피해예측 기법 기술지침의 위험 기준: 화재(복사열)는 5 kW/㎡의 복사열이 미치는 거리로 판단한다.","src":"기출 2023-41"},{"t":"사고 피해예측 기법 기술지침의 위험 기준: 폭발(과압)은 6.9 kPa의 과압이 도달하는 거리로 판단한다.","src":"기출 2023-41"}]}],"함정":[{"x":"정기평가는 최초평가 후 2년에 1회 실시하여야 한다.","o":"정기 재검토는 최초 평가 결과에 대해 1년마다 실시한다.","src":"사업장 위험성평가에 관한 지침 제15조 | 기출 2022-36"}]},"시스템안전공학 기법(FTA·최소절단집합·PHA·FMEA·CCA·MORT·HAZOP)":{"묶음":[{"머리":"기법별 특징","줄":[{"t":"PHA(예비위험분석): 초기 개발 단계에서 시스템 고유의 위험성을 파악하고 예상되는 재해의 위험수준을 결정한다. 시스템 내 위험요소가 어떤 위험 상태에 있는가를 평가하는 정성적 기법이다.","src":"기출 2022-47 | 기출 2025-34"},{"t":"FMEA: 시스템에 영향을 미치는 모든 요소의 고장을 형태별로 분석하여 그 영향을 검토하는 정성적ㆍ귀납적 기법이다.","src":"기출 2024-48 | 기출 2025-34"},{"t":"FMEA 위험우선순위(RPN) = 심각도(S) × 발생도(O) × 검출도(D). RPN이 가장 높은 고장유형을 우선 조치한다.","src":"기출 2025-39 | 보충"},{"t":"RPN 비교 예: (S,O,D) = (5,6,3)→90, (6,5,4)→120, (7,4,3)→84, (8,3,2)→48, (9,3,4)→108. 최대는 120.","src":"기출 2025-39"},{"t":"MORT: FTA와 동일한 논리방법을 사용하여 관리, 설계, 생산 및 보전 등의 넓은 범위에 걸친 안전 확보를 위해 활용하는 기법. 원자력 산업 등에 이용된다.","src":"기출 2021-37 | 기출 2025-34"},{"t":"HEA: 운전원, 보수반원, 기술자 등의 불안전행동으로 발생할 수 있는 피해에 대해 그 원인을 파악ㆍ추적하여 문제점을 개선하기 위한 평가기법.","src":"기출 2025-34"},{"t":"CA(위험도 분석, Criticality Analysis)에서 작업의 실패로 이어질 염려가 있는 고장은 카테고리 Ⅱ다.","src":"기출 2021-38"},{"t":"CA 고장 영향 카테고리: Ⅰ 생명 또는 가옥의 상실(치명), Ⅱ 작업(임무) 수행 실패, Ⅲ 활동 지연, Ⅳ 영향 없음.","src":"기출 2021-38 | 보충"},{"t":"FTA는 연역적(하향식) 정량적 기법, ETA와 FMEA는 귀납적 기법이다.","src":"보충"},{"t":"ETA(사건수분석): 초기 사건에서 시작해 이원적(성공/실패) 분기로 결과를 전개하는 귀납적 기법.","src":"보충"},{"t":"CCA(원인결과분석): 결함수(FT)와 사건수(ET)를 결합해 잠재된 사고의 결과와 근본 원인 사이의 상호관계를 예측하고 리스크를 평가한다.","src":"기출 2025-34 | 보충"},{"t":"CCA 평가절차: 평가할 사건의 선정 → 안전요소의 확인 → 사건수의 구성 → 결함수의 구성 → 최소컷세트 평가 → 결과의 문서화.","src":"기출 2023-28"},{"t":"공정안전성 분석(K-PSR) 기술지침 위험형태: 누출, 화재ㆍ폭발, 공정 트러블, 상해.","src":"기출 2023-36"},{"t":"HAZOP: 공정의 설계 의도에서 벗어난 이탈을 가이드워드로 체계적으로 찾아 위험과 운전성 문제를 평가하는 기법.","src":"보충"}]},{"머리":"HAZOP 가이드워드","줄":[{"t":"no/not: 설계 의도의 완전한 부정.","src":"기출 2025-38"},{"t":"more/less: 양의 증가 혹은 감소.","src":"기출 2025-38"},{"t":"as well as: 성질상의 증가.","src":"기출 2025-38 | 보충"},{"t":"part of: 성질상의 감소(성질상의 증가가 아님).","src":"기출 2025-38 | 보충"},{"t":"reverse: 설계 의도의 논리적인 역.","src":"기출 2025-38"},{"t":"other than: 완전한 대체.","src":"기출 2025-38"}]},{"머리":"시스템 안전성 확보 방법","줄":[{"t":"시스템 안전성 확보 방법: 위험상태 존재의 최소화, 안전장치의 채용, 경보장치의 채택, 인간공학적 설계의 적용.","src":"기출 2022-48"},{"t":"중복설계(redundancy)는 안전성 확보를 위해 채택한다. 중복설계의 배제는 안전성 확보 방법이 아니다.","src":"기출 2022-48"}]},{"머리":"결함수(FT)와 최소절단집합","줄":[{"t":"AND 게이트는 모든 입력이 발생해야 출력, OR 게이트는 하나라도 발생하면 출력. 최소컷셋은 정상사상을 일으키는 기본사상의 최소 조합이다.","src":"보충"},{"t":"계산 방법: 게이트를 위에서 아래로 전개해 AND는 곱(같이 묶음), OR는 합(분리)으로 쓰고 불대수(A·A=A, A+AB=A)로 간소화한다.","src":"보충"},{"t":"예: T = (a+b)·(a·c) = a·c 이므로 최소절단집합은 {a, c}다.","src":"기출 2024-46"},{"t":"예: A1이 x1·x2·x3(AND), A2가 x4+x5(OR)이고 T가 A1·A2(AND)이면 최소절단집합은 (x1,x2,x3,x4), (x1,x2,x3,x5)다.","src":"기출 2025-36"},{"t":"불대수 간소화 예: A̅B̅C̅ + A̅BC̅ + AB̅C̅ + AB̅C + ABC̅ + ABC = C̅ + AC = A + C̅.","src":"기출 2025-42"},{"t":"XOR(배타적 논리합): 입력이 서로 다르면 1, 같으면 0. (0,0)→0, (1,1)→0, (0,1)→1. OR: (0,1)→1.","src":"기출 2026-38"},{"t":"FT 결과 {a}, {c}처럼 단일 사상이 각각 컷셋이면 두 사상이 OR 관계로 정상사상에 연결된 것이다.","src":"기출 2022-49 | 보충"}]}],"함정":[{"x":"HAZOP은 잠재된 사고의 결과 및 근본적인 원인을 찾아내고 사고결과와 원인 사이의 상호관계를 예측하며 리스크를 평가하는 기법이다.","o":"그 설명은 원인결과분석(CCA)에 해당한다. HAZOP은 설계 의도에서 벗어난 이탈을 가이드워드로 찾아 위험과 운전성 문제를 평가하는 기법이다.","src":"기출 2025-34 | 보충"}]},"안전성평가 단계와 기술개발종합평가":{"묶음":[{"머리":"안전성평가 6단계","줄":[{"t":"1단계: 관계 자료의 작성 준비.","src":"보충"},{"t":"2단계: 정성적 평가.","src":"기출 2023-39"},{"t":"3단계: 정량적 평가.","src":"기출 2023-39"},{"t":"4단계: 안전대책.","src":"기출 2023-39"},{"t":"5단계: 재해정보에 의한 재평가.","src":"기출 2023-39"},{"t":"6단계: FTA에 의한 재평가(ETA가 아님).","src":"기출 2023-39 | 보충"},{"t":"정량적 평가 위험등급(합산 점수): 16점 이상 Ⅰ등급, 11~15점 Ⅱ등급, 10점 이하 Ⅲ등급.","src":"보충(원문 미확인)"}]},{"머리":"기술개발의 종합평가(Technology Assessment)","줄":[{"t":"기술개발 종합평가의 단계별 내용으로 2단계 실현가능성, 3단계 안전성 및 위험성, 4단계 경제성, 5단계 종합평가는 옳은 것으로 출제됐다.","src":"기출 2022-50"},{"t":"1단계가 생산성 및 보전성이라는 보기는 옳지 않은 것으로 출제됐다. 1단계의 바른 내용은 원문 미확인.","src":"기출 2022-50"}]}],"함정":[]},"신뢰성공학(신뢰도이론·욕조곡선·지수분포·직렬병렬 계산·예방보전)":{"묶음":[{"머리":"신뢰도 기본 함수","줄":[{"t":"F(t) = 1 - R(t): 불신뢰도(고장분포함수)와 신뢰도는 합이 1.","src":"기출 2025-37"},{"t":"f(t) = dF(t)/dt: 고장밀도함수는 불신뢰도의 시간 미분.","src":"기출 2025-37"},{"t":"h(t) = f(t) ÷ (1 - F(t)) = f(t) ÷ R(t): 고장률함수. [df/dt ÷ (1-F)]는 고장률이 아니다.","src":"기출 2025-37"},{"t":"지수분포: R(t) = e^(-λt), 평균수명(MTBF) = 1/λ, 불신뢰도 F(t) = 1 - e^(-λt).","src":"기출 2023-42 | 기출 2024-49 | 보충"},{"t":"지수분포는 우발적인 고장을 다루는 데 적합하다.","src":"기출 2022-44"},{"t":"지수분포는 무기억성(memoryless property)을 갖는다.","src":"기출 2022-44"},{"t":"지수분포에서 평균(1/λ)은 중앙값(ln2/λ ≈ 0.693/λ)보다 크다(평균이 중앙값보다 작다는 보기는 틀림).","src":"기출 2022-44 | 보충"},{"t":"계산: 평균고장률 10^-2/h, 3시간(180분) 작동 → F = 1 - e^(-0.03) ≈ 0.03.","src":"기출 2023-42"},{"t":"계산: 평균수명 10^4 h, 10^3 h 작동 → R = e^(-0.1) ≈ 0.905 → 0.90.","src":"기출 2024-49"},{"t":"포아송 분포: 연평균 1회인 사고가 3년간 0건일 확률 = e^(-3) ≈ 0.05.","src":"기출 2022-46"}]},{"머리":"욕조곡선","줄":[{"t":"욕조곡선: 초기고장기(고장률 감소형), 우발고장기(고장률 일정형), 마모고장기(고장률 증가형)로 나뉜다.","src":"기출 2022-41 | 보충"},{"t":"초기고장기는 번인(burn-in)·디버깅으로, 마모고장기는 예방보전·교체로 대응한다.","src":"보충"}]},{"머리":"직렬·병렬 계산","줄":[{"t":"직렬계 신뢰도 = R1 × R2 × … × Rn.","src":"보충"},{"t":"병렬계 신뢰도 = 1 - (1-R1)(1-R2)…(1-Rn).","src":"보충"},{"t":"동일 부품 A 4개 병렬의 신뢰도가 0.9984 → (1-A)^4 = 0.0016 → 1-A = 0.2 → A = 0.8.","src":"기출 2023-38"},{"t":"a-b 직렬 경로 2개를 병렬로 연결한 시스템의 신뢰도 = 1 - (1-ab)^2.","src":"기출 2025-40"}]},{"머리":"보전·가용도·안전무결성","줄":[{"t":"예방보전: 시간기반보전, 상태기반보전, 수명기반보전, 기회보전 등. 고장보전(사후보전)은 예방보전이 아니다.","src":"기출 2022-45"},{"t":"가용도(Availability): 사후 보전 관점에서 설비시스템이 어떤 시점에서 요구기능을 수행할 수 있는 상태에 있을 확률.","src":"기출 2026-36"},{"t":"가용도 A = MTBF ÷ (MTBF + MTTR). 정비도(Maintainability)는 정해진 시간 내에 수리를 완료할 확률.","src":"보충"},{"t":"안전무결성등급(SIL) 목표평균 고장확률: SIL 1은 10^-2 이상~10^-1 미만, SIL 4는 10^-5 이상~10^-4 미만.","src":"기출 2023-34"},{"t":"SIL 2는 10^-3 이상~10^-2 미만, SIL 3은 10^-4 이상~10^-3 미만(저요구 모드 평균 고장확률).","src":"보충"},{"t":"인간-기계체계 신뢰도 유지의 피드백 제어방식: 서보 메커니즘, 프로세스 컨트롤, 오토매틱 레귤레이션 모두 해당.","src":"기출 2021-35"}]}],"함정":[]},"인간-기계체계와 표시장치ㆍ조종장치 설계":{"묶음":[{"머리":"인간-기계 시스템 설계","줄":[{"t":"인간-기계시스템 설계과정 6단계: 목표 및 성능명세 결정 → 시스템 정의 → 기본설계 → 인터페이스 설계 → 촉진물·보조물 설계 → 시험 및 평가.","src":"기출 2023-40"},{"t":"인간-기계 인터페이스는 인간-기계 시스템을 구성하는 요소다.","src":"기출 2024-38"},{"t":"표시장치는 기계의 상태 정보를 인간에게 전달하는 장치다(인간의 반응을 표시하는 장치가 아님).","src":"기출 2024-38 | 보충"},{"t":"작업자가 전동 공구로 제품을 조립하는 과정은 인간-기계 시스템에 해당한다.","src":"기출 2024-38 | 보충"},{"t":"인간의 주관적 반응은 인간 기준(human criteria)에 해당한다. 시스템 기준(system-descriptive criteria)이 아니다.","src":"기출 2024-38 | 보충"},{"t":"심박수는 생리적 지표(인간 기준)에 해당한다. 인간 성능 척도(performance measure)가 아니다.","src":"기출 2024-38 | 보충"},{"t":"인간의 수행도 평가척도: 정신적 작업부하, 오류 횟수, 사용자 만족도, 학습시간.","src":"기출 2026-42"},{"t":"자동화수준은 인간 수행도 평가척도로 출제되지 않았다(옳지 않은 것).","src":"기출 2026-42"},{"t":"설계 원칙: 성별·연령 등 사용자 특성 고려, 직관적 인터페이스, 조작 장애물 제거로 접근 용이, 인적오류에 의한 사고가능성 방지.","src":"기출 2026-41"},{"t":"반드시 최신기술을 사용하도록 설계한다는 것은 설계 원칙이 아니다.","src":"기출 2026-41"},{"t":"인간공학 적용 기대효과: 생산성 향상, 직무만족도 향상, 노사간 신뢰 구축, 산재손실비용 감소, 이직률 감소.","src":"기출 2025-43 | 보충"},{"t":"닐슨(J. Nielsen)의 사용성 속성: 학습 용이성, 효율성, 기억 용이성, 오류의 빈도와 정도, 주관적 만족도.","src":"기출 2022-35 | 보충"},{"t":"적합성(conformity)은 닐슨의 사용성 속성이 아니다.","src":"기출 2022-35"}]},{"머리":"표시장치와 조종장치","줄":[{"t":"작업자의 즉각적 행동이 필요한 경우 청각적 표시장치가 시각적 표시장치보다 유리하다.","src":"기출 2022-34"},{"t":"330 m 이상의 장거리에 신호를 전달할 때는 청각 신호의 주파수를 1,000 Hz 이하로 한다.","src":"기출 2022-34"},{"t":"광삼현상(irradiation)으로 인해 음각(검은 바탕의 흰 글씨)의 글자 획폭은 양각(흰 바탕의 검은 글씨)보다 작은 값이 권장된다.","src":"기출 2022-34"},{"t":"공간적 양립성은 표시장치와 조종장치의 배치와 관련된다.","src":"기출 2022-34"},{"t":"양립성 종류: 공간적, 운동, 개념, 양식 양립성.","src":"보충"},{"t":"조종-반응 비(C/R 비)가 작을수록 민감도가 높아 미세조종이 어렵다. C/R 비가 클수록 민감도가 낮아 미세조종에 유리하다.","src":"기출 2022-34 | 보충"},{"t":"통제표시비(C/D 비) = 조종장치 이동량 ÷ 표시장치 이동량. 회전 조종구는 (각도/360 × 2π × 반지름)을 이동량으로 쓴다.","src":"기출 2023-47 | 보충"},{"t":"계산: 반지름 30 cm 조종구를 20° 회전, 지침 2 cm 이동 → (20/360 × 2π × 30) ÷ 2 ≈ 5.23.","src":"기출 2023-47"},{"t":"작업장 도구·부품·조종장치 배치 원리: 일관성, 중요도, 사용 순서, 사용 빈도(기능별 배치). 독창성 원리는 없다.","src":"기출 2022-33 | 기출 2026-44"},{"t":"청각적 표시장치 일반원리: 근사성, 검약성, 분리성, 양립성, 불변성. 변동성은 일반원리가 아니다.","src":"기출 2025-50 | 보충"},{"t":"시각적 표시장치가 유리한 경우: 복잡하고 긴 메시지, 후에 참조할 메시지, 소음이 큰 환경. 청각적 표시장치가 유리한 경우: 간단하고 짧은 메시지, 즉각 행동이 필요한 경우, 시각이 과부하인 경우.","src":"보충"}]}],"함정":[{"x":"조종-반응 비(C/R 비)가 작을수록 조종장치와 표시장치의 민감도가 낮아져 미세조종에 유리하다.","o":"C/R 비가 작을수록 민감도가 높아져 미세조종이 어렵다. C/R 비가 클수록 민감도가 낮아 미세조종에 유리하다.","src":"기출 2022-34 | 보충"},{"x":"인간-기계 시스템에서 표시장치는 인간의 반응을 표시하는 장치를 의미한다.","o":"표시장치는 기계·시스템의 상태 정보를 인간에게 전달하는 장치다.","src":"기출 2024-38 | 보충"},{"x":"작업자가 전동 공구를 사용하여 제품을 조립하는 과정은 인간-기계 시스템에 해당하지 않는다.","o":"전동 공구로 조립하는 작업도 인간(작업자)과 기계(공구)가 상호작용하므로 인간-기계 시스템에 해당한다.","src":"기출 2024-38 | 보충"},{"x":"인간의 주관적 반응은 인간-기계 시스템의 평가기준 중 시스템 기준(system-descriptive criteria)에 해당한다.","o":"주관적 반응은 인간 기준(human criteria)에 해당한다.","src":"기출 2024-38 | 보충"},{"x":"인간-기계 시스템을 평가할 때 심박수는 인간 성능에 관한 척도(performance measure)에 해당한다.","o":"심박수는 생리적 지표(인간 기준)이며 성능 척도가 아니다.","src":"기출 2024-38 | 보충"},{"x":"반드시 최신기술을 사용하도록 설계한다.","o":"인간-기계 설계는 사용자 특성과 안전을 우선 고려한다. 최신기술 사용 자체는 설계 원칙이 아니다.","src":"기출 2026-41"}]},"물리적 작업환경(조도·색채·소음·착시·자동운동·열교환)":{"묶음":[{"머리":"조도","줄":[{"t":"작업면 조도 기준: 초정밀작업 750럭스 이상.","src":"산업안전보건기준에 관한 규칙 제8조 | 기출 2021-42"},{"t":"작업면 조도 기준: 정밀작업 300럭스 이상.","src":"산업안전보건기준에 관한 규칙 제8조 | 기출 2021-42"},{"t":"작업면 조도 기준: 보통작업 150럭스 이상.","src":"산업안전보건기준에 관한 규칙 제8조"},{"t":"작업면 조도 기준: 그 밖의 작업 75럭스 이상.","src":"산업안전보건기준에 관한 규칙 제8조"},{"t":"조도 기준의 예외: 갱내 작업장과 감광재료를 취급하는 작업장.","src":"산업안전보건기준에 관한 규칙 제8조"}]},{"머리":"소음","줄":[{"t":"소음작업: 1일 8시간 작업을 기준으로 85데시벨 이상의 소음이 발생하는 작업.","src":"산업안전보건기준에 관한 규칙 제512조"},{"t":"강렬한 소음작업: 90dB 이상 1일 8시간 이상, 95dB 이상 4시간 이상, 100dB 이상 2시간 이상, 105dB 이상 1시간 이상, 110dB 이상 30분 이상, 115dB 이상 15분 이상.","src":"산업안전보건기준에 관한 규칙 제512조"},{"t":"충격소음작업: 소음이 1초 이상의 간격으로 발생하며, 120dB 초과 소음이 1일 1만회 이상, 130dB 초과 1천회 이상, 140dB 초과 1백회 이상인 작업.","src":"산업안전보건기준에 관한 규칙 제512조 | 기출 2023-50"},{"t":"1초 간격으로 125dB 소음이 1일 1만회 발생하는 작업은 충격소음작업이다.","src":"기출 2024-39 | 산업안전보건기준에 관한 규칙 제512조"},{"t":"진동작업 기계·기구: 착암기, 동력을 이용한 해머, 체인톱, 엔진 커터, 동력을 이용한 연삭기, 임팩트 렌치, 그 밖에 진동으로 건강장해를 유발할 수 있는 기계ㆍ기구.","src":"산업안전보건기준에 관한 규칙 제512조 | 기출 2024-39"},{"t":"청력보존 프로그램 내용: 소음노출 평가, 공학적 대책, 청력보호구 지급·착용, 소음의 유해성 및 예방 관련 교육, 정기적 청력검사, 시행 관련 기록·관리체계, 그 밖의 필요 사항.","src":"산업안전보건기준에 관한 규칙 제512조 | 기출 2024-39"},{"t":"1일 8시간 기준 90dB 소음 발생 작업은 소음작업(85dB 이상)에 해당한다.","src":"기출 2024-39 | 산업안전보건기준에 관한 규칙 제512조"},{"t":"105dB 소음이 1일 30분 발생하는 작업은 강렬한 소음작업이 아니다(105dB은 1시간 이상 필요).","src":"기출 2024-39 | 산업안전보건기준에 관한 규칙 제512조"},{"t":"소음 노출기준(충격소음 제외): 1일 노출시간 8시간 90dB(A), 4시간 95dB(A), 2시간 100dB(A), 1시간 105dB(A).","src":"기출 2021-40 | 보충(원문 미확인)"},{"t":"거리와 음압: 점음원에서 거리가 2배가 될 때마다 음압수준이 약 6dB 감소한다. 거리가 10배면 20dB 감소.","src":"보충"},{"t":"계산: 30m에서 140dB이면 300m(10배)에서 140 - 20 = 120dB.","src":"기출 2021-32"},{"t":"sone: 1,000Hz 순음 40dB(phon)을 1 sone으로 정의하고 10phon 증가마다 2배. 80dB = 16 sone, 60dB = 4 sone → 4배 크게 들린다.","src":"기출 2024-44 | 보충"},{"t":"음압 합성: L = 10·log10(Σ10^(Li/10)).","src":"보충"}]},{"머리":"시각·색채·착시","줄":[{"t":"망막의 추상체(원추세포)는 색상을 주로 느끼고, 간상체(간상세포)는 명암을 주로 느낀다.","src":"기출 2021-45"},{"t":"명순응된 눈의 최대비시감도는 약 555nm, 암순응된 눈은 약 510nm로 짧은 파장 쪽으로 이동한다(푸르키네 효과).","src":"기출 2021-45 | 기출 2024-40"},{"t":"가장 민감한 빛의 파장은 간상세포가 원추세포보다 짧다.","src":"기출 2024-40"},{"t":"명순응은 암순응에 비해 시간이 짧게 걸린다.","src":"기출 2024-40"},{"t":"암순응 과정에서 원추세포 → 간상세포의 순으로 순응 단계가 진행된다.","src":"기출 2024-40"},{"t":"눈에서 물체까지의 거리가 가까울수록 수정체를 두껍게 하여 초점을 맞춘다. 멀어지면 수정체는 얇아진다.","src":"기출 2024-40 | 보충"},{"t":"최소가분시력(minimum separable acuity): 일정 거리에서 구분할 수 있는 표적의 최소 크기에 따라 정해진다.","src":"기출 2024-40"},{"t":"시력 = 1 ÷ 최소 분별 시각(분). 시각(분) ≈ 3,438 × 틈 크기 ÷ 거리.","src":"보충"},{"t":"계산: 5m에서 1.5mm 틈을 구분 → 시각 ≈ 1.03분 → 시력 ≈ 1.0.","src":"기출 2021-46"},{"t":"계산: 시력 1.2, 6m → 최소 시각 0.833분 → 틈 ≈ 1.45mm ≈ 1.5mm.","src":"기출 2022-39"},{"t":"자동운동: 암실에서 정지된 작은 빛을 응시하면 움직이는 것처럼 보이는 현상. 광점이 작고, 광의 강도가 작으며, 시야의 다른 부분이 어둡고, 대상이 단순할 때 생기기 쉽다.","src":"기출 2023-45"}]},{"머리":"열환경","줄":[{"t":"옥스퍼드(Oxford) 지수(WD) = 0.85 × 습구온도 + 0.15 × 건구온도.","src":"기출 2021-39 | 보충"},{"t":"계산: 건구 42℃, 습구 32℃ → 0.85×32 + 0.15×42 = 33.5℃.","src":"기출 2021-39"},{"t":"WBGT(옥외, 일사 있음) = 0.7×자연습구 + 0.2×흑구 + 0.1×건구. WBGT(옥내 또는 일사 없음) = 0.7×자연습구 + 0.3×흑구.","src":"보충"},{"t":"열교환 식: S(열축적) = M(대사열) - W(일) ± R(복사) ± C(대류) - E(증발).","src":"보충"}]}],"함정":[{"x":"105데시벨의 소음이 1일 30분 발생하는 작업은 강렬한 소음작업에 해당한다.","o":"105dB 소음은 1일 1시간 이상 발생해야 강렬한 소음작업이다. 30분 이상이면 110dB부터 해당한다.","src":"산업안전보건기준에 관한 규칙 제512조 | 기출 2024-39"},{"x":"눈에서 물체까지의 거리가 멀어질수록 수정체의 두께를 두껍게 하여 초점을 맞춘다.","o":"거리가 가까울수록 수정체를 두껍게, 멀어질수록 얇게 하여 초점을 맞춘다.","src":"기출 2024-40 | 보충"}]},"인간의 정보처리와 인적오류(정보이론·SRK모델·THERP)":{"묶음":[{"머리":"정보이론","줄":[{"t":"정보량(bit) = log2(대안 수). 동일 발생확률의 신호 N개이면 정보량 = log2 N.","src":"기출 2026-43 | 보충"},{"t":"계산: 동일 확률 8개 신호의 정보량 = log2 8 = 3 bit.","src":"기출 2026-43"},{"t":"일반 정보량: H = Σ p_i · log2(1/p_i).","src":"보충"}]},{"머리":"SRK 모델과 인적오류","줄":[{"t":"라스무센(Rasmussen)의 SRK 모델: 숙련 기반(Skill), 규칙 기반(Rule), 지식 기반(Knowledge) 행동 수준.","src":"기출 2022-43 | 보충"},{"t":"리전(Reason)의 인적오류: 실수(slip)와 망각(lapse)은 비의도적 행동으로 분류되는 숙련 기반 오류다.","src":"기출 2022-43"},{"t":"잘못된 규칙을 적용하는 것은 규칙 기반 착오(mistake)이며 의도적 행동에 속한다(비의도적 행동으로 분류한다는 보기는 틀림).","src":"기출 2022-43 | 보충"},{"t":"불충분한 정보로 인해 잘못된 결정을 내리는 것은 의도적 행동으로 분류되는 지식 기반 착오(mistake)다.","src":"기출 2022-43"},{"t":"규정을 알면서 어기는 위반(violation)은 의도적 행동이다.","src":"보충"}]},{"머리":"THERP","줄":[{"t":"THERP: 시스템에 있어서 인간의 과오를 정량적으로 평가하기 위해 개발된 기법.","src":"기출 2026-39"},{"t":"THERP: 초기 사건을 이원적(binary) 의사결정 가지들로 모형화한다.","src":"기출 2026-39"},{"t":"THERP: 각 작업의 성공 또는 실패 확률을 부여하여 각 경로의 확률을 계산한다.","src":"기출 2026-39"},{"t":"THERP: 최종적으로 민감도 분석이나 통계분석 등을 통하여 결과를 통합한다.","src":"기출 2026-39"},{"t":"사람이 틀리게 조작하더라도 안전하게 되도록 하는 것은 풀프루프(fool proof) 개념이다. THERP가 아니다.","src":"기출 2026-39 | 보충"}]}],"함정":[{"x":"사람이 작동하는 시스템에서 사람이 틀리게 조작하더라도 안전하게 되도록 하는 기법이다.","o":"이 설명은 풀프루프(fool proof)에 해당한다. THERP는 인간 과오를 정량 평가하는 기법이다.","src":"기출 2026-39 | 보충"}]},"근골격계 부담작업과 작업공간ㆍ인체측정 설계":{"묶음":[{"머리":"법령: 유해요인조사와 예방관리","줄":[{"t":"근골격계질환: 반복적인 동작, 부적절한 작업자세, 무리한 힘의 사용, 날카로운 면과의 신체접촉, 진동 및 온도 등의 요인에 의하여 발생하는 건강장해로서 목, 어깨, 허리, 팔ㆍ다리의 신경ㆍ근육 및 그 주변 신체조직 등에 나타나는 질환.","src":"산업안전보건기준에 관한 규칙 제656조"},{"t":"근골격계질환 예방관리 프로그램: 유해요인 조사, 작업환경 개선, 의학적 관리, 교육ㆍ훈련, 평가에 관한 사항 등이 포함된 종합적인 계획.","src":"산업안전보건기준에 관한 규칙 제656조"},{"t":"사업주는 근로자가 근골격계부담작업을 하는 경우 3년마다 유해요인조사를 해야 한다. 신설 사업장은 신설일부터 1년 이내에 최초 조사를 한다.","src":"산업안전보건기준에 관한 규칙 제657조 | 기출 2024-42"},{"t":"유해요인조사 항목: 설비ㆍ작업공정ㆍ작업량ㆍ작업속도 등 작업장 상황, 작업시간ㆍ작업자세ㆍ작업방법 등 작업조건, 작업과 관련된 근골격계질환 징후와 증상 유무.","src":"산업안전보건기준에 관한 규칙 제657조 | 기출 2024-42"},{"t":"수시 유해요인조사 사유: 근골격계질환자 발생(임시건강진단 등)·업무상 질병 인정, 근골격계부담작업에 해당하는 새로운 작업ㆍ설비 도입, 업무의 양과 작업공정 등 작업환경 변경. 사유 발생 시 1개월 이내에 조사한다(2024 기출 보기는 새 작업·설비 도입 시 '지체 없이').","src":"산업안전보건기준에 관한 규칙 제657조 | 기출 2024-42"},{"t":"유해요인 조사에는 근로자대표 또는 해당 작업 근로자를 참여시켜야 한다.","src":"산업안전보건기준에 관한 규칙 제657조"},{"t":"조사 방법: 근로자와의 면담, 증상 설문조사, 인간공학적 측면을 고려한 조사 등.","src":"산업안전보건기준에 관한 규칙 제658조"},{"t":"조사 결과 근골격계질환이 발생할 우려가 있으면 인간공학적으로 설계된 인력작업 보조설비 및 편의설비를 설치하는 등 작업환경을 개선한다.","src":"산업안전보건기준에 관한 규칙 제659조"},{"t":"예방관리 프로그램 수립·시행 대상: 업무상 질병 인정 근골격계질환자가 연간 10명 이상 발생한 사업장, 또는 5명 이상 발생하고 그 비율이 근로자 수의 10% 이상인 사업장. 노사 이견이 지속되어 고용노동부장관이 명령한 경우도 해당.","src":"산업안전보건기준에 관한 규칙 제662조 | 기출 2024-42"},{"t":"예방관리 프로그램 작성ㆍ시행 시 노사협의를 거쳐야 하고, 인간공학ㆍ산업의학ㆍ산업위생ㆍ산업간호 등 전문가의 지도ㆍ조언을 받을 수 있다.","src":"산업안전보건기준에 관한 규칙 제662조"},{"t":"5킬로그램 이상 중량물을 인력으로 들어올리는 작업: 주로 취급하는 물품의 중량과 무게중심을 작업장 주변에 안내표시하고, 취급이 곤란한 물품은 손잡이·갈고리·진공빨판 등 보조도구를 활용한다.","src":"산업안전보건기준에 관한 규칙 제665조 | 기출 2024-42"}]},{"머리":"근골격계부담작업의 범위(고시)","줄":[{"t":"단기간 작업: 2개월 이내에 종료되는 1회성 작업. 간헐적인 작업: 연간 총 작업일수가 60일을 초과하지 않는 작업. 이 둘은 부담작업에서 제외한다.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제2조·제3조"},{"t":"1호: 하루에 4시간 이상 집중적으로 자료입력 등을 위해 키보드 또는 마우스를 조작하는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조 | 기출 2025-49"},{"t":"2호: 하루에 총 2시간 이상 목, 어깨, 팔꿈치, 손목 또는 손을 사용하여 같은 동작을 반복하는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조 | 기출 2025-49"},{"t":"3호: 하루에 총 2시간 이상 머리 위에 손이 있거나, 팔꿈치가 어깨 위에 있거나, 팔꿈치를 몸통으로부터 들거나 몸통 뒤쪽에 위치하는 상태의 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"4호: 지지되지 않거나 임의로 자세를 바꿀 수 없는 조건에서 하루에 총 2시간 이상 목이나 허리를 구부리거나 트는 상태의 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"5호: 하루에 총 2시간 이상 쪼그리고 앉거나 무릎을 굽힌 자세에서 이루어지는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조 | 기출 2025-49"},{"t":"6호: 하루에 총 2시간 이상 지지되지 않은 상태에서 1kg 이상의 물건을 한손의 손가락으로 집어 옮기거나, 2kg 이상에 상응하는 힘을 가하여 한손의 손가락으로 물건을 쥐는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"7호: 하루에 총 2시간 이상 지지되지 않은 상태에서 4.5kg 이상의 물건을 한 손으로 들거나 동일한 힘으로 쥐는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"8호: 하루에 10회 이상 25kg 이상의 물체를 드는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조 | 기출 2025-49"},{"t":"9호: 하루에 25회 이상 10kg 이상의 물체를 무릎 아래에서 들거나, 어깨 위에서 들거나, 팔을 뻗은 상태에서 드는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"10호: 하루에 총 2시간 이상, 분당 2회 이상 4.5kg 이상의 물체를 드는 작업(2.5kg 이상이 아님).","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조 | 기출 2025-49"},{"t":"11호: 하루에 총 2시간 이상 시간당 10회 이상 손 또는 무릎을 사용하여 반복적으로 충격을 가하는 작업.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제3조"},{"t":"유해요인조사는 유해요인조사표와 근골격계질환 증상조사표를 활용한다.","src":"근골격계부담작업의 범위 및 유해요인조사 방법에 관한 고시 제4조"}]},{"머리":"작업평가 기법","줄":[{"t":"RULA는 상지·목·몸통과 함께 하지 자세를 평가에 반영한다.","src":"기출 2022-40"},{"t":"REBA는 동작의 반복성(활동 점수)을 평가에 반영한다.","src":"기출 2022-40"},{"t":"REBA는 손으로 물체를 잡을 때 손잡이 조건(coupling)을 평가에 반영한다.","src":"기출 2024-43"},{"t":"REBA는 보행 동작을 평가에 반영하지 않는다.","src":"기출 2024-43"},{"t":"QEC는 작업자의 주관적 평가 과정이 포함되어 있다.","src":"기출 2022-40"},{"t":"OWAS는 허리·팔·다리 자세와 중량물 취급 정도(하중)를 평가에 반영한다. 팔꿈치 각도는 반영하지 않는다.","src":"기출 2022-40 | 기출 2024-43"},{"t":"NLE(NIOSH Lifting Equation): RWL = LC × HM × VM × DM × AM × FM × CM. LC = 23kg.","src":"보충"},{"t":"NLE 변수: 수평거리(H), 수직높이(V), 이동거리(D, 수직), 비대칭각(A), 빈도(F), 결합(손잡이, C).","src":"보충"},{"t":"NLE는 중량물의 수평 이동(운반)거리를 반영하지 않는다. 수평거리는 손과 신체 중심 사이의 거리(H)다.","src":"기출 2022-40 | 기출 2024-43 | 보충"},{"t":"NLE의 LI(들기지수) = 실제 중량 ÷ RWL. 값이 클수록 위험하며 LI > 1이면 개선이 필요하다.","src":"기출 2024-43 | 보충"}]},{"머리":"작업설계와 인체측정","줄":[{"t":"동작경제 원칙: 양손은 동시에 시작하고 동시에 끝나도록 한다.","src":"기출 2023-37"},{"t":"동작경제 원칙: 양팔의 동작은 동시에 서로 반대방향으로 대칭적으로 움직이도록 한다.","src":"기출 2023-37"},{"t":"동작경제 원칙: 손과 신체동작은 작업을 원만하게 수행할 수 있는 범위 내에서 가장 낮은 동작 등급을 사용한다.","src":"기출 2023-37"},{"t":"동작경제 원칙: 족답장치를 활용하여 양손이 다른 일을 할 수 있도록 한다.","src":"기출 2023-37"},{"t":"동작경제 원칙: 휴식시간을 제외하고는 양손이 동시에 쉬지 않도록 한다.","src":"기출 2023-37"},{"t":"제품 설계에 인체 측정치를 적용하는 절차: 설계에 필요한 인체치수 선택 → 인체측정 자료 응용 원리 결정 → 적절한 인체측정 자료 선택 → 필요한 여유치 결정.","src":"기출 2024-41"},{"t":"인체측정 자료 응용 원리: 극단치(최대·최소) 설계, 조절식 설계, 평균치 설계.","src":"보충"},{"t":"작업공간: 한 장소에 앉아서 수행하는 작업활동에서 사람이 작업하는 데 사용하는 공간.","src":"기출 2026-44"},{"t":"수평작업대 정상작업역: 윗팔을 자연스럽게 수직으로 늘어뜨린 상태에서 아래팔만으로 편하게 뻗어서 파악할 수 있는 구역.","src":"기출 2026-44"},{"t":"앉은 자세 작업 의자는 높이를 조정할 수 있게 설계한다(반드시 고정이 아님).","src":"기출 2026-44 | 기출 2025-48"},{"t":"선자세 중량물 취급 작업대 높이는 팔꿈치 높이보다 약간 낮게 설계한다.","src":"기출 2026-44"},{"t":"작업공간 배치(부품 배치)는 중요성, 사용빈도, 기능별 배치 등을 고려한다.","src":"기출 2026-44"},{"t":"의자 설계 일반원칙: 척추의 요부전만 유지, 디스크가 받는 압력 감소, 등근육의 정적 부하 감소, 조정이 용이할 것. 정적 자세고정을 증가시키는 것은 원칙에 어긋난다.","src":"기출 2025-48"},{"t":"동작 유형: 굴곡은 관절에서 각도가 감소하는 동작, 신전은 관절에서 각도가 증가하는 동작이다.","src":"기출 2026-45 | 보충"},{"t":"동작 유형: 내전은 몸의 중심선으로 향하는 이동, 외전은 중심선에서 멀어지는 이동. 내선은 중심선 쪽으로의 회전, 외선은 중심선으로부터의 회전.","src":"기출 2026-45 | 보충"},{"t":"기출 2026-45는 정답 보기를 ㄱ 신전, ㄴ 외전, ㄷ 내선(선지 2번)으로 기록하고 있다. 표준 정의(내전은 중심선으로 향함)와 어긋나므로 출제 원문 재확인이 필요하다.","src":"기출 2026-45"}]},{"머리":"손·손목 부위 근골격계 질환","줄":[{"t":"손과 손목 부위 질환: 드퀘르벵 건초염(De Quervain's tenosynovitis), 결절종(Ganglion), 가이언 증후군(Canal of Guyon), 바르텐베르그 증후군(Wartenberg's syndrome).","src":"기출 2026-46"},{"t":"회내근 증후군(Pronator syndrome)은 손과 손목 부위 질환이 아닌 것으로 출제됐다(팔꿈치·전완 부위).","src":"기출 2026-46 | 보충"}]}],"함정":[{"x":"근골격계질환 예방과 관련하여 노사 간 이견(異見)이 없는 근로자 수 80명인 사업장에서 연간 업무상 질병으로 인정받은 근골격계질환자가 5명 발생한 경우에 근골격계질환 예방관리 프로그램을 수립 및 시행해야 한다.","o":"5명 이상 발생해도 발생 비율이 근로자 수의 10% 이상(80명이면 8명 이상)이어야 한다. 연간 10명 이상이면 비율과 무관하게 대상이다.","src":"산업안전보건기준에 관한 규칙 제662조 | 기출 2024-42"},{"x":"NLE는 중량물의 수평 이동거리를 평가에 반영한다.","o":"NLE는 수평거리(손과 신체 중심 사이)를 반영하나 수평 이동(운반)거리는 반영하지 않는다.","src":"기출 2022-40 | 기출 2024-43 | 보충"},{"x":"NLE의 LI는 값이 클수록 안전한 작업이다.","o":"LI가 클수록 위험한 작업이다. LI가 1을 넘으면 개선이 필요하다.","src":"기출 2024-43 | 보충"},{"x":"REBA는 보행 동작을 평가에 반영한다.","o":"REBA는 보행 동작을 평가에 반영하지 않는다.","src":"기출 2024-43"},{"x":"NLE는 중량물의 수평 운반거리를 평가에 반영한다.","o":"NLE는 수평 운반거리를 평가에 반영하지 않는다.","src":"기출 2024-43"},{"x":"OWAS는 팔꿈치 각도를 평가에 반영한다.","o":"OWAS는 허리·팔·다리 자세와 하중을 평가하며 팔꿈치 각도는 반영하지 않는다.","src":"기출 2024-43 | 보충"},{"x":"양손은 동시에 시작하고 동시에 끝나지 않도록 한다.","o":"양손은 동시에 시작하고 동시에 끝나도록 한다.","src":"기출 2023-37"},{"x":"앉은 자세에서 작업을 할 경우 의자의 높이가 반드시 고정되도록 설계해야 한다.","o":"의자 높이는 조정이 가능하도록 설계한다.","src":"기출 2026-44 | 기출 2025-48"}]},"산업심리(리더십ㆍ동기부여이론ㆍ의식수준)":{"묶음":[{"머리":"의식 수준(Phase)","줄":[{"t":"Phase 0: 무의식·실신 상태. 신뢰성 0.","src":"기출 2021-43 | 보충"},{"t":"Phase Ⅰ: 의식이 둔한 상태(피로·단조·졸음). 신뢰성 0.9 이하.","src":"기출 2021-43 | 보충"},{"t":"Phase Ⅱ: 이완·편안한 상태(정상, 안정). 신뢰성 0.99~0.99999.","src":"기출 2021-43 | 보충"},{"t":"Phase Ⅲ: 명석한 상태(정상, 적극적 활동). 신뢰성 0.999999 이상.","src":"기출 2021-43"},{"t":"Phase Ⅳ: 과긴장·흥분 상태(당황, 공황). 신뢰성 0.9 이하.","src":"기출 2021-43 | 보충"}]},{"머리":"매슬로우 욕구 5단계","줄":[{"t":"제1단계: 생리적 욕구(생명유지의 기본적 욕구).","src":"기출 2023-49"},{"t":"제2단계: 안전 및 안정 욕구(도전 욕구가 아님).","src":"기출 2023-49 | 기출 2026-31"},{"t":"제3단계: 사회적 욕구(소속감과 애정 욕구).","src":"기출 2023-49"},{"t":"제4단계: 존경(자기 존중) 욕구. 인정받으려는 욕구, 회사나 자신에 대한 명예ㆍ명성을 유지하려는 동기.","src":"기출 2023-49 | 기출 2026-31"},{"t":"제5단계: 자아실현 욕구(잠재적 능력의 실현 욕구).","src":"기출 2023-49"}]},{"머리":"리더십 이론","줄":[{"t":"관리격자이론(Blake & Mouton): 생산에 대한 관심과 인간에 대한 관심의 정도로 리더십을 구분한다.","src":"보충"},{"t":"(9,1)형 과업형: 생산에 관한 관심은 대단히 높으나 인간에 대한 관심이 극히 낮다.","src":"기출 2021-47"},{"t":"(1,1)형 무관심형: 생산·인간 모두 낮다. (1,9)형 컨트리클럽형: 인간 높고 생산 낮다. (5,5)형 중도형. (9,9)형 팀형(이상형).","src":"보충"}]},{"머리":"적응기제","줄":[{"t":"합리화: 어떤 행동이 억압되었을 때 그 행동이 사회적으로 용납될 수 있는 이유를 설명함으로써 자아를 보호하는 행동.","src":"기출 2025-29"},{"t":"백일몽: 현실적으로 도저히 만족할 수 없는 욕구나 소원을 상상의 세계에서 얻으려고 하는 행동.","src":"기출 2025-29"},{"t":"승화: 억압당한 욕구가 사회적, 문화적으로 가치 있는 목적으로 향하여 노력함으로써 욕구를 충족시키는 것.","src":"기출 2025-29"},{"t":"동일시: 타인의 성공이나 특성을 자신과 같은 것으로 여겨 만족을 얻는 기제. 보상: 한 분야의 열등감을 다른 분야의 우월로 보충하는 기제.","src":"보충"},{"t":"투사: 자신의 결함이나 불만을 다른 사람 탓으로 돌리는 기제.","src":"보충"}]},{"머리":"동기부여 이론 (표준 교과)","줄":[{"t":"허즈버그 2요인 이론: 위생요인(불만 방지)과 동기요인(만족·성과 유발)으로 구분한다.","src":"보충"},{"t":"맥그리거 X·Y 이론: X이론은 통제·지시, Y이론은 자율·참여를 전제한다.","src":"보충"},{"t":"알더퍼 ERG 이론: 존재(Existence), 관계(Relatedness), 성장(Growth).","src":"보충"},{"t":"맥클랜드 성취동기 이론: 성취욕구, 권력욕구, 친교욕구.","src":"보충"}]}],"함정":[{"x":"Phase 0의 의식상태는 무의식 상태이며 신뢰성은 0.3이다.","o":"Phase 0은 무의식·실신 상태이며 신뢰성은 0이다.","src":"기출 2021-43 | 보충"},{"x":"Phase 1의 의식상태는 실신 상태이며 신뢰성은 0.6이상이다.","o":"Phase Ⅰ은 의식이 둔한 상태(피로·단조·졸음)이며 신뢰성은 0.9 이하다.","src":"기출 2021-43 | 보충"},{"x":"Phase 2의 의식상태는 의식이 둔한 상태이며 신뢰성은 0.9이다.","o":"Phase Ⅱ는 이완·편안한 정상 상태이며 신뢰성은 0.99~0.99999다.","src":"기출 2021-43 | 보충"},{"x":"Phase 4의 의식상태는 편안한 상태이며 신뢰성은 1.0이다.","o":"Phase Ⅳ는 과긴장·흥분 상태이며 신뢰성은 0.9 이하다.","src":"기출 2021-43 | 보충"},{"x":"제2단계: 도전 욕구(새로운 것에 대한 도전 욕구)","o":"매슬로우 제2단계는 안전 및 안정 욕구다.","src":"기출 2023-49 | 기출 2026-31"}]},"안전 관련 법령ㆍ고시 적용(안전보건표지·특별교육 대상·제조물책임법·안전검사 고시 등)":{"묶음":[{"머리":"산업안전보건위원회","줄":[{"t":"사업주는 사업장의 안전 및 보건에 관한 중요 사항을 심의ㆍ의결하기 위하여 근로자위원과 사용자위원이 같은 수로 구성되는 산업안전보건위원회를 구성ㆍ운영해야 한다.","src":"산업안전보건법 제24조"},{"t":"위원회 심의ㆍ의결 사항: 법 제15조제1항제1호~제5호 및 제7호에 관한 사항(산재 예방계획 수립, 안전보건관리규정 작성·변경, 안전보건교육, 작업환경측정 등 점검·개선, 건강진단 등 건강관리, 산업재해 통계의 기록·유지).","src":"산업안전보건법 제24조 | 기출 2023-31"},{"t":"위원회 심의ㆍ의결 사항: 법 제15조제1항제6호(산업재해 원인 조사 및 재발 방지대책 수립) 중 중대재해에 관한 사항.","src":"산업안전보건법 제24조 | 기출 2026-32"},{"t":"위원회 심의ㆍ의결 사항: 유해하거나 위험한 기계ㆍ기구ㆍ설비를 도입한 경우 안전 및 보건 관련 조치에 관한 사항.","src":"산업안전보건법 제24조 | 기출 2023-31"},{"t":"위원회 심의ㆍ의결 사항: 그 밖에 해당 사업장 근로자의 안전 및 보건을 유지ㆍ증진시키기 위하여 필요한 사항.","src":"산업안전보건법 제24조"},{"t":"안전장치 및 보호구 구입 시 적격품 여부 확인(법 제15조제1항제8호)은 위원회 심의ㆍ의결 사항에 포함되지 않는다.","src":"산업안전보건법 제24조 | 기출 2025-33 | 기출 2026-32"},{"t":"공정안전보고서를 작성할 때 위원회의 심의를 거친다(위원회가 없으면 근로자대표 의견 청취).","src":"산업안전보건법 제44조 | 기출 2026-32"},{"t":"안전보건개선계획을 수립할 때 위원회의 심의를 거친다(위원회가 없으면 근로자대표 의견 청취).","src":"산업안전보건법 제49조 | 기출 2026-32"},{"t":"위원회는 법, 명령, 단체협약, 취업규칙, 안전보건관리규정에 반하는 내용으로 심의ㆍ의결해서는 안 된다. 위원에게 직무 수행 관련 불리한 처우를 해서는 안 된다.","src":"산업안전보건법 제24조"},{"t":"위원회 구성 대상 - 상시근로자 50명 이상: 토사석 광업, 목재 및 나무제품 제조업(가구 제외), 화학물질 및 화학제품 제조업(의약품 제외; 세제·화장품·광택제·화학섬유 제외), 비금속 광물제품 제조업, 1차 금속 제조업, 금속가공제품 제조업(기계 및 가구 제외), 자동차 및 트레일러 제조업, 기타 기계 및 장비 제조업(사무용 제외), 기타 운송장비 제조업(전투용 차량 제외).","src":"산업안전보건법 시행령 별표 9"},{"t":"위원회 구성 대상 - 상시근로자 300명 이상: 농업, 어업, 소프트웨어 개발 및 공급업, 컴퓨터 프로그래밍·시스템 통합 및 관리업, 영상ㆍ오디오물 제공 서비스업, 정보서비스업, 금융 및 보험업, 임대업(부동산 제외), 전문·과학 및 기술 서비스업(연구개발업 제외), 사업지원 서비스업, 사회복지 서비스업.","src":"산업안전보건법 시행령 별표 9"},{"t":"위원회 구성 대상 - 건설업: 공사금액 120억원 이상(토목공사업은 150억원 이상). 위 업종 외의 사업은 상시근로자 100명 이상.","src":"산업안전보건법 시행령 별표 9"},{"t":"근로자위원: 근로자대표, 명예산업안전감독관이 위촉되어 있으면 근로자대표가 지명하는 1명 이상의 명예산업안전감독관, 근로자대표가 지명하는 9명 이내의 해당 사업장 근로자.","src":"산업안전보건법 시행령 제35조"},{"t":"사용자위원: 해당 사업의 대표자, 안전관리자 1명, 보건관리자 1명, 산업보건의(선임된 경우), 대표자가 지명하는 9명 이내의 해당 사업장 부서의 장.","src":"산업안전보건법 시행령 제35조"},{"t":"상시근로자 50명 이상 100명 미만 사업장에서는 사용자위원 중 대표자가 지명하는 9명 이내의 부서의 장을 제외하고 구성할 수 있다.","src":"산업안전보건법 시행령 제35조 | 기출 2021-48"},{"t":"건설공사도급인이 안전 및 보건에 관한 협의체를 구성한 경우 위원회를 도급·하도급 전체 사업을 포함하여 구성할 수 있다(근로자위원: 전체 사업 근로자대표 등, 사용자위원: 도급인 대표자·관계수급인 대표자·안전관리자).","src":"산업안전보건법 시행령 제35조"}]},{"머리":"안전보건관리책임자와 담당자","줄":[{"t":"안전보건관리책임자 업무 1: 사업장의 산업재해 예방계획의 수립에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 2: 안전보건관리규정의 작성 및 변경에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 3: 안전보건교육에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 4: 작업환경측정 등 작업환경의 점검 및 개선에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 5: 근로자의 건강진단 등 건강관리에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 6: 산업재해의 원인 조사 및 재발 방지대책 수립에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 7: 산업재해에 관한 통계의 기록 및 유지에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 8: 안전장치 및 보호구 구입 시 적격품 여부 확인에 관한 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자 업무 9: 그 밖에 근로자의 유해ㆍ위험 방지조치에 관한 사항으로서 고용노동부령으로 정하는 사항.","src":"산업안전보건법 제15조"},{"t":"안전보건관리책임자는 안전관리자와 보건관리자를 지휘ㆍ감독한다.","src":"산업안전보건법 제15조"},{"t":"사업주는 안전보건관리책임자가 업무를 원활히 수행하도록 권한ㆍ시설ㆍ장비ㆍ예산 등 필요한 지원을 하고, 선임 사실과 업무 수행내용을 증명할 서류를 갖춰 두어야 한다.","src":"산업안전보건법 시행령 제14조"},{"t":"안전보건관리책임자 선임 - 상시근로자 50명 이상: 토사석 광업, 식료품·음료 제조업, 목재 및 나무제품 제조업(가구 제외), 펄프·종이 제조업, 코크스·연탄·석유정제품 제조업, 화학물질·화학제품 제조업(의약품 제외), 의료용 물질 및 의약품 제조업, 고무 및 플라스틱제품 제조업, 비금속 광물제품 제조업, 1차 금속 제조업, 금속가공제품 제조업, 전자부품·컴퓨터·영상·음향·통신장비 제조업, 의료·정밀·광학기기 및 시계 제조업, 전기장비 제조업, 기타 기계 및 장비 제조업, 자동차 및 트레일러 제조업, 기타 운송장비 제조업, 가구 제조업, 기타 제품 제조업, 서적·잡지 및 기타 인쇄물 출판업, 해체·선별 및 원료 재생업, 자동차 종합 수리업·전문 수리업.","src":"산업안전보건법 시행령 별표 2 | 기출 2025-35"},{"t":"안전보건관리책임자 선임 - 상시근로자 300명 이상: 농업, 어업, 소프트웨어 개발 및 공급업, 컴퓨터 프로그래밍·시스템 통합 및 관리업, 영상ㆍ오디오물 제공 서비스업, 정보서비스업, 금융 및 보험업, 임대업(부동산 제외), 전문·과학 및 기술 서비스업(연구개발업 제외), 사업지원 서비스업, 사회복지 서비스업.","src":"산업안전보건법 시행령 별표 2 | 기출 2025-35"},{"t":"안전보건관리책임자 선임 - 건설업은 공사금액 20억원 이상. 그 밖의 사업은 상시근로자 100명 이상.","src":"산업안전보건법 시행령 별표 2"},{"t":"소프트웨어 개발 및 공급업은 300명 이상이므로 50명 이상이라는 연결은 옳지 않다. 의료용 물질 및 의약품 제조업 50명, 금융 및 보험업 300명, 해체·선별 및 원료 재생업 50명, 정보서비스업 300명은 옳다.","src":"산업안전보건법 시행령 별표 2 | 기출 2025-35"},{"t":"안전보건관리담당자 업무 1: 안전보건교육 실시에 관한 보좌 및 지도ㆍ조언.","src":"산업안전보건법 시행령 제25조 | 기출 2024-29"},{"t":"안전보건관리담당자 업무 2: 위험성평가에 관한 보좌 및 지도ㆍ조언.","src":"산업안전보건법 시행령 제25조 | 기출 2024-29"},{"t":"안전보건관리담당자 업무 3: 작업환경측정 및 개선에 관한 보좌 및 지도ㆍ조언.","src":"산업안전보건법 시행령 제25조 | 기출 2024-29"},{"t":"안전보건관리담당자 업무 4: 각종 건강진단에 관한 보좌 및 지도ㆍ조언.","src":"산업안전보건법 시행령 제25조"},{"t":"안전보건관리담당자 업무 5: 산업재해 발생의 원인 조사, 산업재해 통계의 기록 및 유지를 위한 보좌 및 지도ㆍ조언(통계의 유지ㆍ관리ㆍ분석을 위한 보좌가 아님).","src":"산업안전보건법 시행령 제25조 | 기출 2024-29"},{"t":"안전보건관리담당자 업무 6: 안전장치 및 보호구 구입 시 적격품 선정에 관한 보좌 및 지도ㆍ조언.","src":"산업안전보건법 시행령 제25조 | 기출 2024-29"}]},{"머리":"안전보건진단과 안전보건개선계획","줄":[{"t":"개선계획 수립 명령 대상 1: 산업재해율이 같은 업종의 규모별 평균 산업재해율보다 높은 사업장.","src":"산업안전보건법 제49조"},{"t":"개선계획 수립 명령 대상 2: 사업주가 필요한 안전조치 또는 보건조치를 이행하지 않아 중대재해가 발생한 사업장.","src":"산업안전보건법 제49조 | 기출 2022-32"},{"t":"개선계획 수립 명령 대상 3: 대통령령으로 정하는 수 이상의 직업성 질병자가 발생한 사업장.","src":"산업안전보건법 제49조"},{"t":"개선계획 수립 명령 대상 3의2: 법 제56조제1항제2호에 따른 산업재해가 발생한 사업장으로서 대통령령으로 정하는 사업장.","src":"산업안전보건법 제49조"},{"t":"개선계획 수립 명령 대상 4: 법 제106조에 따른 유해인자의 노출기준을 초과한 사업장.","src":"산업안전보건법 제49조"},{"t":"안전보건진단을 받아 개선계획을 수립하라고 명할 수 있는 사업장: 산업재해율이 같은 업종 평균의 2배 이상인 사업장.","src":"산업안전보건법 시행령 제49조 | 기출 2022-32"},{"t":"안전보건진단 명령 대상: 중대재해가 발생한 사업장(사업주가 안전조치·보건조치를 이행하지 않은 경우).","src":"산업안전보건법 시행령 제49조 | 기출 2022-32"},{"t":"안전보건진단 명령 대상: 직업성 질병자가 연간 2명 이상 발생한 사업장(상시근로자 1천명 이상 사업장은 3명 이상).","src":"산업안전보건법 시행령 제49조 | 기출 2022-32"},{"t":"안전보건진단 명령 대상: 작업환경 불량, 화재ㆍ폭발 또는 누출 사고 등으로 사업장 주변까지 피해가 확산된 사업장으로서 고용노동부령으로 정하는 사업장.","src":"산업안전보건법 시행령 제49조 | 기출 2022-32"},{"t":"산업재해율이 같은 업종 평균의 1.5배인 사업장은 안전보건진단 명령 대상이 아니다(2배 이상이어야 함).","src":"산업안전보건법 시행령 제49조 | 기출 2022-32"},{"t":"개선계획서는 수립ㆍ시행 명령을 받은 날부터 60일 이내에 관할 지방고용노동관서의 장에게 제출한다.","src":"산업안전보건법 시행규칙 제61조 | 기출 2024-27"},{"t":"개선계획서 포함 사항: 시설, 안전보건관리체제, 안전보건교육, 산업재해 예방 및 작업환경의 개선을 위하여 필요한 사항.","src":"산업안전보건법 시행규칙 제61조 | 기출 2024-27"},{"t":"지방고용노동관서의 장은 개선계획서를 접수한 날부터 15일 이내에 심사하여 사업주에게 결과를 알려야 한다.","src":"산업안전보건법 시행규칙 제62조"},{"t":"지방고용노동관서의 장은 개선계획서의 적정 여부 확인을 공단 또는 지도사에게 요청할 수 있다.","src":"산업안전보건법 시행규칙 제62조 | 기출 2024-27"},{"t":"고용노동부장관은 제출받은 개선계획서의 보완을 명할 수 있다. 사업주와 근로자는 심사를 받은 개선계획서를 준수해야 한다.","src":"산업안전보건법 제50조"}]},{"머리":"유해위험방지계획서 제출 대상","줄":[{"t":"제조업 13종(금속가공제품 제조업(기계·가구 제외), 비금속 광물제품, 기타 기계 및 장비, 자동차 및 트레일러, 식료품, 고무제품 및 플라스틱제품, 목재 및 나무제품, 기타 제품, 1차 금속, 가구, 화학물질 및 화학제품, 반도체, 전자부품 제조업)으로서 전기 계약용량이 300킬로와트 이상인 경우.","src":"산업안전보건법 시행령 제42조 | 기출 2026-40"},{"t":"제출 대상 기계ㆍ기구 및 설비: 금속이나 그 밖의 광물의 용해로, 화학설비, 건조설비, 가스집합 용접장치, 근로자의 건강에 장해를 일으킬 우려가 있는 물질로서 고용노동부령으로 정하는 물질의 밀폐ㆍ환기ㆍ배기 설비.","src":"산업안전보건법 시행령 제42조"},{"t":"건설공사 대상: 지상높이 31미터 이상인 건축물 또는 인공구조물의 건설ㆍ개조 또는 해체.","src":"산업안전보건법 시행령 제42조 | 기출 2024-45"},{"t":"건설공사 대상: 연면적 3만제곱미터 이상인 건축물의 건설ㆍ개조 또는 해체.","src":"산업안전보건법 시행령 제42조 | 기출 2024-45"},{"t":"건설공사 대상: 연면적 5천제곱미터 이상인 문화 및 집회시설(전시장 및 동물원·식물원 제외), 판매시설, 운수시설(고속철도 역사 및 집배송시설 제외), 종교시설, 의료시설 중 종합병원, 숙박시설 중 관광숙박시설, 지하도상가, 냉동ㆍ냉장 창고시설의 건설등 공사.","src":"산업안전보건법 시행령 제42조 | 기출 2024-45 | 기출 2026-40"},{"t":"건설공사 대상: 연면적 5천제곱미터 이상인 냉동ㆍ냉장 창고시설의 설비공사 및 단열공사.","src":"산업안전보건법 시행령 제42조 | 기출 2026-40"},{"t":"건설공사 대상: 최대 지간길이가 50미터 이상인 다리의 건설등 공사.","src":"산업안전보건법 시행령 제42조 | 기출 2026-40"},{"t":"건설공사 대상: 터널의 건설등 공사.","src":"산업안전보건법 시행령 제42조"},{"t":"건설공사 대상: 다목적댐, 발전용댐, 저수용량 2천만톤 이상의 용수 전용 댐 및 지방상수도 전용 댐의 건설등 공사.","src":"산업안전보건법 시행령 제42조"},{"t":"건설공사 대상: 깊이 10미터 이상인 굴착공사.","src":"산업안전보건법 시행령 제42조 | 기출 2024-45"},{"t":"판정 사례: 지상높이 25m 건축물 건설은 대상 아님(31m 미만). 연면적 2만㎡ 건축물 해체는 대상 아님(3만㎡ 미만). 연면적 6천㎡ 판매시설 건설, 깊이 12m 굴착공사는 대상.","src":"산업안전보건법 시행령 제42조 | 기출 2024-45"},{"t":"판정 사례: 연면적 5천㎡ 전시장 건설은 대상 아님(전시장 제외). 지간 60m 다리, 전기 계약용량 350kW 가구제조업, 연면적 6천㎡ 냉동ㆍ냉장 창고시설의 설비·단열공사는 대상.","src":"산업안전보건법 시행령 제42조 | 기출 2026-40"}]},{"머리":"안전인증·안전검사·대여자 안전조치","줄":[{"t":"안전인증대상 기계·설비 9종: 프레스, 전단기 및 절곡기, 크레인, 리프트, 압력용기, 롤러기, 사출성형기, 고소작업대, 곤돌라.","src":"산업안전보건법 시행령 제74조"},{"t":"안전인증대상 방호장치: 프레스 및 전단기 방호장치, 양중기용 과부하 방지장치, 보일러 압력방출용 안전밸브, 압력용기 압력방출용 안전밸브, 압력용기 압력방출용 파열판, 절연용 방호구 및 활선작업용 기구, 방폭구조 전기기계ㆍ기구 및 부품, 추락ㆍ낙하 및 붕괴 등 방지 가설기자재(고시), 산업용 로봇 방호장치(고시).","src":"산업안전보건법 시행령 제74조"},{"t":"안전인증대상 보호구 12종: 추락 및 감전 위험방지용 안전모, 안전화, 안전장갑, 방진마스크, 방독마스크, 송기마스크, 전동식 호흡보호구, 보호복, 안전대, 차광 및 비산물 위험방지용 보안경, 용접용 보안면, 방음용 귀마개 또는 귀덮개.","src":"산업안전보건법 시행령 제74조"},{"t":"설치ㆍ이전하는 경우 안전인증을 받아야 하는 기계: 크레인, 리프트, 곤돌라.","src":"산업안전보건법 시행규칙 제107조 | 기출 2025-44"},{"t":"주요 구조 부분을 변경하는 경우 안전인증을 받아야 하는 기계·설비: 프레스, 전단기 및 절곡기, 크레인, 리프트, 압력용기, 롤러기, 사출성형기, 고소작업대, 곤돌라.","src":"산업안전보건법 시행규칙 제107조 | 기출 2025-44"},{"t":"설치·이전과 주요 구조 부분 변경 두 경우 모두 안전인증을 받는 기계는 크레인, 리프트, 곤돌라다.","src":"산업안전보건법 시행규칙 제107조 | 기출 2025-44"},{"t":"안전검사대상기계등 15종: 프레스, 전단기, 크레인(정격하중 2톤 미만 제외), 리프트, 압력용기, 곤돌라, 국소 배기장치(이동식 제외), 원심기(산업용), 롤러기(밀폐형 제외), 사출성형기(형 체결력 294kN 미만 제외), 고소작업대(화물자동차·특수자동차 탑재), 컨베이어, 산업용 로봇, 혼합기, 파쇄기 또는 분쇄기.","src":"산업안전보건법 시행령 제78조"},{"t":"안전검사 대상 압력용기(화학공정 유체취급용기 또는 그 밖의 공정에 사용하는 용기 중 공기 또는 질소취급용기): 설계압력이 게이지 압력으로 0.2메가파스칼을 초과한 경우.","src":"안전검사 절차에 관한 고시 별표 1 | 기출 2026-50"},{"t":"대여자 등이 안전조치 등을 해야 하는 기계ㆍ기구ㆍ설비 및 건축물: 사무실 및 공장용 건축물, 이동식 크레인, 타워크레인, 불도저, 모터 그레이더, 로더, 스크레이퍼, 스크레이퍼 도저, 파워 셔블, 드래그라인, 클램셸, 버킷굴착기, 트렌치, 항타기, 항발기, 어스드릴, 천공기, 어스오거, 페이퍼드레인머신, 리프트, 지게차, 롤러기, 콘크리트 펌프, 고소작업대, 그 밖에 고시하는 것.","src":"산업안전보건법 시행령 별표 21 | 기출 2021-30"},{"t":"안전모 종류: AB종(물체의 낙하·비래 및 추락 위험 방지), AE종(물체의 낙하·비래 위험 방지, 내전압성), ABE종(낙하·비래 및 추락 방지, 내전압성).","src":"보호구 안전인증 고시 별표 1"},{"t":"안전모 시험성능기준 항목: 내관통성, 충격흡수성, 내전압성, 내수성, 난연성, 턱끈풀림. 내약품성은 항목이 아니다.","src":"보호구 안전인증 고시 별표 1 | 기출 2021-29"},{"t":"내관통성: AE·ABE종 관통거리 9.5mm 이하, AB종 11.1mm 이하. 충격흡수성: 최고전달충격력 4,450N 이하. 내전압성: AE·ABE종 교류 20kV 1분간 절연파괴 없이 견디고 충전전류 10mA 이하. 내수성: AE·ABE종 질량증가율 1% 미만. 난연성: 모체가 불꽃을 내며 5초 이상 연소되지 않을 것. 턱끈풀림: 150N 이상 250N 이하에서 풀릴 것.","src":"보호구 안전인증 고시 별표 1"},{"t":"안전모 일반구조: 착용높이 85mm 이상, 외부수직거리 80mm 미만, 내부수직거리 25mm 이상 50mm 미만, 수평간격 5mm 이상, 턱끈 폭 10mm 이상.","src":"보호구 안전인증 고시 별표 1"}]},{"머리":"안전보건표지 색도기준","줄":[{"t":"빨간색 7.5R 4/14: 금지(정지신호, 소화설비 및 그 장소, 유해행위의 금지)와 경고(화학물질 취급장소에서의 유해ㆍ위험 경고).","src":"산업안전보건법 시행규칙 별표 8 | 기출 2021-44"},{"t":"노란색 5Y 8.5/12: 경고(화학물질 취급장소에서의 유해ㆍ위험경고 이외의 위험경고, 주의표지 또는 기계방호물).","src":"산업안전보건법 시행규칙 별표 8 | 기출 2021-44"},{"t":"파란색 2.5PB 4/10: 지시(특정 행위의 지시 및 사실의 고지).","src":"산업안전보건법 시행규칙 별표 8 | 기출 2021-44"},{"t":"녹색 2.5G 4/10: 안내(비상구 및 피난소, 사람 또는 차량의 통행표지).","src":"산업안전보건법 시행규칙 별표 8 | 기출 2021-44"},{"t":"흰색 N9.5: 파란색 또는 녹색에 대한 보조색. 검은색 N0.5: 문자 및 빨간색 또는 노란색에 대한 보조색.","src":"산업안전보건법 시행규칙 별표 8"},{"t":"N9.5는 화학물질 취급장소 유해ㆍ위험 경고의 색도가 아니다(그것은 빨간색 7.5R 4/14).","src":"산업안전보건법 시행규칙 별표 8 | 기출 2021-44"},{"t":"색도 허용 오차: 색상 H ±2, 명도 V ±0.3, 채도 C ±1. 색도기준은 KS A 0062에 따른다.","src":"산업안전보건법 시행규칙 별표 8"}]},{"머리":"특별교육 대상 작업(총 39종)","줄":[{"t":"특별교육 1호: 고압실 내 작업(잠함공법이나 그 밖의 압기공법으로 대기압을 넘는 기압인 작업실 또는 수갱 내부 작업).","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 2호: 아세틸렌 용접장치 또는 가스집합 용접장치를 사용하는 금속의 용접·용단 또는 가열작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 3호: 밀폐된 장소(탱크 내 또는 환기가 극히 불량한 좁은 장소)에서 하는 용접작업 또는 습한 장소에서 하는 전기용접 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 4호: 폭발성·물반응성·자기반응성·자기발열성 물질, 자연발화성 액체·고체 및 인화성 액체의 제조 또는 취급작업(시험연구용 취급작업 제외).","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 5호: 액화석유가스·수소가스 등 인화성 가스 또는 폭발성 물질 중 가스의 발생장치 취급 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 6호: 화학설비 중 반응기, 교반기·추출기의 사용 및 세척작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 7호: 화학설비의 탱크 내 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 8호: 분말·원재료 등을 담은 호퍼·저장창고 등 저장탱크의 내부작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 9호: 건조설비에 의한 물건의 가열·건조작업(위험물 등 관계 설비로 속부피 1세제곱미터 이상, 또는 연료 열원 최대연소소비량 시간당 10킬로그램 이상·전력 열원 정격소비전력 10킬로와트 이상).","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 10호: 집재장치(원동기 정격출력 7.5킬로와트 초과, 지간 경사거리 합계 350미터 이상, 최대사용하중 200킬로그램 이상)의 조립·해체·변경·수리 및 이들에 의한 집재·운반 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 11호: 동력에 의하여 작동되는 프레스기계를 5대 이상 보유한 사업장에서 해당 기계로 하는 작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2022-29"},{"t":"특별교육 12호: 목재가공용 기계(둥근톱기계, 띠톱기계, 대패기계, 모떼기기계, 라우터기; 휴대용 제외)를 5대 이상 보유한 사업장에서 해당 기계로 하는 작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2025-30"},{"t":"특별교육 13호: 운반용 등 하역기계를 5대 이상 보유한 사업장에서의 해당 기계로 하는 작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2025-30"},{"t":"특별교육 14호: 1톤 이상의 크레인을 사용하는 작업, 또는 1톤 미만의 크레인 또는 호이스트를 5대 이상 보유한 사업장에서 해당 기계로 하는 작업(제39호 제외).","src":"산업안전보건법 시행규칙 별표 5 | 기출 2025-30"},{"t":"특별교육 15호: 건설용 리프트·곤돌라를 이용한 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 16호: 주물 및 단조 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 17호: 전압이 75볼트 이상인 정전 및 활선작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2023-26"},{"t":"특별교육 18호: 콘크리트 파쇄기를 사용하여 하는 파쇄작업(2미터 이상인 구축물의 파쇄작업만 해당).","src":"산업안전보건법 시행규칙 별표 5 | 기출 2023-26"},{"t":"특별교육 19호: 굴착면의 높이가 2미터 이상이 되는 지반 굴착(터널 및 수직갱 외의 갱 굴착 제외) 작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2023-26"},{"t":"특별교육 20호: 흙막이 지보공의 보강 또는 동바리를 설치하거나 해체하는 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 21호: 터널 안에서의 굴착작업 또는 같은 작업에서의 터널 거푸집 지보공의 조립 또는 콘크리트 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 22호: 굴착면의 높이가 2미터 이상이 되는 암석의 굴착작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 23호: 높이가 2미터 이상인 물건을 쌓거나 무너뜨리는 작업(하역기계로만 하는 작업 제외).","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 24호: 선박에 짐을 쌓거나 부리거나 이동시키는 작업.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2023-26"},{"t":"특별교육 25호: 거푸집 동바리의 조립 또는 해체작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 26호: 비계의 조립·해체 또는 변경작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 27호: 건축물의 골조, 다리의 상부구조 또는 탑의 금속제 부재(5미터 이상)의 조립·해체 또는 변경작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 28호: 처마 높이가 5미터 이상인 목조건축물의 구조 부재 조립이나 건축물의 지붕 또는 외벽 밑에서의 설치작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 29호: 콘크리트 인공구조물(높이 2미터 이상)의 해체 또는 파괴작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 30호: 타워크레인을 설치(상승작업 포함)·해체하는 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 31호: 보일러(소형 보일러와 일정 규모 이하 보일러 제외)의 설치 및 취급 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 32호: 게이지 압력을 제곱센티미터당 1킬로그램 이상으로 사용하는 압력용기의 설치 및 취급작업(제곱미터당이 아님).","src":"산업안전보건법 시행규칙 별표 5 | 기출 2023-26"},{"t":"특별교육 33호: 방사선 업무에 관계되는 작업(의료 및 실험용 제외).","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 34호: 밀폐공간에서의 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 35호: 허가 또는 관리 대상 유해물질의 제조 또는 취급작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 36호: 로봇작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 37호: 석면해체·제거작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 38호: 가연물이 있는 장소에서 하는 화재위험작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"특별교육 39호: 타워크레인을 사용하는 작업 시 신호업무를 하는 작업.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"프레스 특별교육 내용: 프레스의 특성과 위험성, 방호장치 종류와 취급, 안전작업방법, 프레스 안전기준, 그 밖에 안전·보건관리에 필요한 사항. 국소배기장치 및 안전설비에 관한 사항은 포함되지 않는다.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2022-29"},{"t":"특별교육 공통내용: 제1호~제39호 작업 모두 채용 시·작업내용 변경 시 교육 내용(다목)과 같은 공통내용을 교육하고, 작업별 개별내용을 더한다.","src":"산업안전보건법 시행규칙 별표 5"},{"t":"정격하중 2.8톤 천장주행크레인 1대·호이스트 보유 작업은 특별교육 대상(14호). 3톤 지게차 1대(13호는 5대 이상), 목재가공 기계 4대(12호는 5대 이상)는 대상이 아니다.","src":"산업안전보건법 시행규칙 별표 5 | 기출 2025-30"}]},{"머리":"산업안전보건기준에 관한 규칙: 점검·달기구","줄":[{"t":"양중기 달기구 안전계수(절단하중 ÷ 최대 하중): 근로자 탑승 운반구를 지지하는 달기와이어로프·달기체인 10 이상, 화물 하중을 직접 지지하는 달기와이어로프·달기체인 5 이상, 훅·샤클·클램프·리프팅 빔 3 이상, 그 밖의 경우 4 이상.","src":"산업안전보건기준에 관한 규칙 제163조"},{"t":"달기구는 최대허용하중 등의 표식이 견고하게 붙어 있는 것을 사용해야 한다.","src":"산업안전보건기준에 관한 규칙 제163조"},{"t":"작업도구 목적 외 사용금지: 훅의 입구 간격이 제조자 제공 제품사양서 기준으로 10퍼센트 이상 벌어진 것은 폐기한다.","src":"기출 2026-33"},{"t":"작업도구 목적 외 사용금지: 체인의 길이가 제조 당시 길이의 5퍼센트를 초과한 것, 링의 단면지름이 제조 당시 지름의 10퍼센트를 초과하여 감소한 것은 사용하지 않는다.","src":"기출 2026-33"},{"t":"작업시작 전 점검 - 프레스등: 클러치 및 브레이크의 기능, 크랭크축·플라이휠·슬라이드·연결봉 및 연결 나사의 풀림 여부, 1행정 1정지기구·급정지장치 및 비상정지장치의 기능, 슬라이드 또는 칼날에 의한 위험방지 기구의 기능, 프레스의 금형 및 고정볼트 상태, 방호장치의 기능, 전단기의 칼날 및 테이블의 상태.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 공기압축기: 공기저장 압력용기의 외관 상태, 드레인밸브의 조작 및 배수, 압력방출장치의 기능, 언로드밸브의 기능, 윤활유의 상태, 회전부의 덮개 또는 울, 그 밖의 연결 부위의 이상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3 | 기출 2023-43"},{"t":"슬라이드 또는 칼날에 의한 위험방지 기구의 기능은 프레스 점검사항이며 공기압축기 점검사항이 아니다.","src":"산업안전보건기준에 관한 규칙 별표 3 | 기출 2023-43"},{"t":"작업시작 전 점검 - 로봇 교시 등: 외부 전선의 피복 또는 외장의 손상 유무, 매니퓰레이터 작동의 이상 유무, 제동장치 및 비상정지장치의 기능.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 크레인: 권과방지장치·브레이크·클러치 및 운전장치의 기능, 주행로의 상측 및 트롤리가 횡행하는 레일의 상태, 와이어로프가 통하고 있는 곳의 상태.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 이동식 크레인: 권과방지장치나 그 밖의 경보장치의 기능, 브레이크·클러치 및 조정장치의 기능, 와이어로프가 통하고 있는 곳 및 작업장소의 지반상태.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 리프트: 방호장치·브레이크 및 클러치의 기능, 와이어로프가 통하고 있는 곳의 상태. 곤돌라: 방호장치·브레이크의 기능, 와이어로프·슬링와이어 등의 상태.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 양중기 와이어로프등으로 고리걸이작업: 와이어로프등의 이상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 지게차: 제동장치 및 조종장치 기능, 하역장치 및 유압장치 기능, 바퀴의 이상 유무, 전조등·후미등·방향지시기 및 경보장치 기능의 이상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 구내운반차: 제동장치·조종장치, 하역장치·유압장치, 바퀴, 전조등·후미등·방향지시기 및 경음기, 충전장치를 포함한 홀더 등의 결합상태.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 고소작업대: 비상정지장치 및 비상하강 방지장치 기능, 과부하 방지장치 작동 유무(와이어로프·체인 구동방식), 아웃트리거 또는 바퀴의 이상 유무, 작업면의 기울기 또는 요철 유무, 활선작업용 장치의 홈·균열·파손 등 손상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 화물자동차: 제동장치 및 조종장치, 하역장치 및 유압장치, 바퀴의 이상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 컨베이어등: 원동기 및 풀리 기능, 이탈 등의 방지장치 기능, 비상정지장치 기능, 원동기·회전축·기어 및 풀리 등의 덮개 또는 울 등의 이상 유무.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 차량계 건설기계: 브레이크 및 클러치 등의 기능.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 화재위험작업: 작업 준비 및 절차 수립 여부, 인근 가연성물질 방호조치 및 소화기구 비치, 불티 비산방지덮개·방화포, 인화성 액체 증기·가스 환기 조치, 작업근로자 화재예방 및 피난교육 등 비상조치.","src":"산업안전보건기준에 관한 규칙 별표 3"},{"t":"작업시작 전 점검 - 이동식 방폭구조 전기기계ㆍ기구: 전선 및 접속부 상태. 중량물 반복 취급: 올바른 자세 및 복장, 보호구, 온도·습기에 의한 위험 중량물 취급방법, 하역운반기계등의 사용방법. 양화장치: 작동상태, 제한하중 초과 여부. 슬링 등: 훅이 붙어 있는 슬링 매달린 상태, 슬링 상태.","src":"산업안전보건기준에 관한 규칙 별표 3"}]},{"머리":"제조물 책임법","줄":[{"t":"제조물: 제조되거나 가공된 동산(다른 동산이나 부동산의 일부를 구성하는 경우를 포함한다).","src":"제조물 책임법 제2조 | 기출 2023-33"},{"t":"결함: 해당 제조물에 제조상ㆍ설계상 또는 표시상의 결함이 있거나 그 밖에 통상적으로 기대할 수 있는 안전성이 결여되어 있는 것.","src":"제조물 책임법 제2조 | 기출 2024-34"},{"t":"제조상의 결함: 제조업자가 주의의무를 이행하였는지에 관계없이 제조물이 원래 의도한 설계와 다르게 제조ㆍ가공됨으로써 안전하지 못하게 된 경우.","src":"제조물 책임법 제2조"},{"t":"설계상의 결함: 제조업자가 합리적인 대체설계를 채용하였더라면 피해나 위험을 줄이거나 피할 수 있었음에도 대체설계를 채용하지 아니하여 안전하지 못하게 된 경우.","src":"제조물 책임법 제2조"},{"t":"표시상의 결함: 제조업자가 합리적인 설명ㆍ지시ㆍ경고 또는 그 밖의 표시를 하였더라면 피해나 위험을 줄이거나 피할 수 있었음에도 이를 하지 아니한 경우.","src":"제조물 책임법 제2조 | 기출 2023-33"},{"t":"배송상 결함은 법정 결함 유형이 아니다.","src":"제조물 책임법 제2조 | 기출 2024-34"},{"t":"제조업자: ① 제조물의 제조ㆍ가공 또는 수입을 업으로 하는 자 ② 제조물에 성명ㆍ상호ㆍ상표 등 식별 가능한 기호를 사용하여 자신을 ①의 자로 표시하거나 ①의 자로 오인하게 할 표시를 한 자.","src":"제조물 책임법 제2조 | 기출 2023-33"},{"t":"제조업자는 제조물의 결함으로 생명ㆍ신체 또는 재산에 손해(그 제조물에 대하여만 발생한 손해는 제외)를 입은 자에게 그 손해를 배상해야 한다.","src":"제조물 책임법 제3조 | 기출 2023-33"},{"t":"제조업자가 결함을 알면서도 필요한 조치를 취하지 않은 결과 생명 또는 신체에 중대한 손해를 입은 자가 있으면 발생한 손해의 3배를 넘지 않는 범위에서 배상책임을 진다.","src":"제조물 책임법 제3조"},{"t":"징벌적 손해배상액 산정 고려 사항: 고의성의 정도, 결함으로 발생한 손해의 정도, 공급으로 제조업자가 취득한 경제적 이익, 형사처벌 또는 행정처분의 정도, 공급이 지속된 기간 및 규모, 제조업자의 재산상태, 피해구제를 위한 노력 정도.","src":"제조물 책임법 제3조"},{"t":"피해자가 제조업자를 알 수 없는 경우 영리 목적으로 판매·대여 등으로 공급한 자가 배상한다. 다만 피해자 요청을 받고 상당한 기간 내에 제조업자 또는 공급한 자를 고지하면 면한다.","src":"제조물 책임법 제3조"},{"t":"결함 추정 요건: 정상 사용 상태에서 손해 발생, 제조업자의 실질적 지배영역에 속한 원인에서 초래, 결함 없이는 통상 발생하지 않는 손해. 제조업자가 결함 외의 다른 원인을 증명하면 추정이 깨진다.","src":"제조물 책임법 제3조의2"},{"t":"면책사유 1: 제조업자가 해당 제조물을 공급하지 아니하였다는 사실.","src":"제조물 책임법 제4조 | 기출 2025-28"},{"t":"면책사유 2: 공급 당시의 과학ㆍ기술 수준으로는 결함의 존재를 발견할 수 없었다는 사실.","src":"제조물 책임법 제4조 | 기출 2025-28"},{"t":"면책사유 3: 결함이 공급 당시의 법령에서 정하는 기준을 준수함으로써 발생하였다는 사실.","src":"제조물 책임법 제4조 | 기출 2025-28"},{"t":"면책사유 4: 원재료나 부품의 경우 그 원재료나 부품을 사용한 제조물 제조업자의 설계 또는 제작에 관한 지시로 결함이 발생하였다는 사실.","src":"제조물 책임법 제4조 | 기출 2025-28"},{"t":"공급한 후 결함의 존재를 알거나 알 수 있었음에도 손해 방지 조치를 하지 않은 경우 면책사유 2~4를 주장할 수 없다.","src":"제조물 책임법 제4조"},{"t":"'공급 당시 과학·기술 수준으로 결함을 발견할 수 있었다'는 사실은 면책사유가 아니다(발견할 수 없었다는 사실이 면책사유).","src":"제조물 책임법 제4조 | 기출 2025-28"},{"t":"동일한 손해에 대하여 배상할 책임이 있는 자가 2인 이상이면 연대하여 배상한다.","src":"제조물 책임법 제5조 | 기출 2023-33"},{"t":"책임을 배제하거나 제한하는 특약은 무효다. 다만 영업용 재산에 발생한 손해에 관한 특약은 유효하다.","src":"제조물 책임법 제6조"},{"t":"손해배상 청구권은 손해와 책임자를 안 날부터 3년간 행사하지 않으면 소멸하고, 공급한 날부터 10년 이내에 행사해야 한다(누적·잠복 손해는 손해 발생일부터 기산).","src":"제조물 책임법 제7조"}]},{"머리":"산업재해 관련 기타 법정 정의","줄":[{"t":"산업재해: 노무를 제공하는 사람이 업무에 관계되는 건설물ㆍ설비ㆍ원재료ㆍ가스ㆍ증기ㆍ분진 등에 의하거나 작업 또는 그 밖의 업무로 인하여 사망 또는 부상하거나 질병에 걸리는 것.","src":"산업안전보건법 제2조"},{"t":"안전보건진단: 산업재해를 예방하기 위하여 잠재적 위험성을 발견하고 그 개선대책을 수립할 목적으로 조사ㆍ평가하는 것.","src":"산업안전보건법 제2조"},{"t":"작업환경측정: 작업환경 실태를 파악하기 위하여 사업주가 유해인자에 대한 측정계획을 수립한 후 시료를 채취하고 분석ㆍ평가하는 것.","src":"산업안전보건법 제2조"},{"t":"도급인: 물건의 제조·건설·수리 또는 서비스의 제공, 그 밖의 업무를 도급하는 사업주(건설공사발주자 제외). 관계수급인: 도급이 여러 단계에 걸쳐 체결된 경우 각 단계별로 도급받은 사업주 전부.","src":"산업안전보건법 제2조"}]}],"함정":[{"x":"“설계상의 결함”이란 제조업자가 합리적인 설명ㆍ지시ㆍ경고 또는 그 밖의 표시를 하였더라면 해당 제조물에 의하여 발생할 수 있는 피해나 위험을 줄이거 나피할 수 있었음에도 이를 하지 아니한 경우를 말한다.","o":"그 문장은 표시상의 결함 정의다. 설계상의 결함은 합리적인 대체설계를 채용하지 아니하여 안전하지 못하게 된 경우다.","src":"제조물 책임법 제2조 | 기출 2023-33"},{"x":"지방고용노동관서의 장이 안전보건개선계획서를 접수한 경우에는 접수일부터 30일 이내에 심사하여 사업주에게 그 결과를 알려야 한다.","o":"접수일부터 15일 이내에 심사하여 결과를 알려야 한다.","src":"산업안전보건법 시행규칙 제62조 | 기출 2024-27"}]}};
